import React, { Fragment, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "react-toastify";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import { Link } from "react-router-dom";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Books/BookDetails.css";
import {
  getSchoolStudentDetails,
  clearErrors,
  payFeesSchool,
  updateGrade,
  studentPassed,
} from "../../actions/schoolStudentActions";
import {
  payFine,
  clearErrors as clearFineErrors,
} from "../../actions/usersActions";
import {
  PAYMENT_SSTUDENT_RESET,
  UPDATE_GRADE_RESET,
} from "../../constants/schoolStudentConstant";
import FeeSidebar from "../layout/Loader/FeeSidebar";
import { FINE_USER_RESET } from "../../constants/usersConstant";

const SchoolStudentDetails = () => {
  const dispatch = useDispatch();
  const { id } = useParams();

  const { error, schoolStudent } = useSelector(
    (state) => state.schoolStudentDetails
  );
  const {
    error: paymentError,
    isPaid,
    isUpdated,
  } = useSelector((state) => state.schoolStudentProfile);
  const { isFined, error: fineError } = useSelector(
    (state) => state.userProfile
  );

  const [isOpen, setIsOpen] = useState(0);
  const [password, setPassword] = useState();
  const [amount, setAmount] = useState();
  const [paidBy, setPaidBy] = useState();
  const [receiptNo, setReceiptNo] = useState();
  const [discount, setDiscount] = useState();
  const [hostel, setHostel] = useState();
  const [num, setNum] = useState();

  const [showPassword, setShowPassword] = useState(false);

  const openDialog = (num) => {
    setIsOpen(num);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(0);
  };

  const makeNum = (numb) => {
    setNum(numb);
  };

  const paymentSubmit = (e) => {
    e.preventDefault();
    const data = {
      password,
      receiptNo,
      paidBy,
      amount,
    };
    closeDialog();
    try {
      dispatch(payFeesSchool(id, data));
    } catch (err) {}
  };

  const updateSubmit = (e) => {
    e.preventDefault();
    const data = {
      password,
      discount,
      hostel,
      grade: schoolStudent.grade < 12 ? schoolStudent.grade + 1 : 100,
    };
    closeDialog();
    if(schoolStudent.grade != 12) {
      try {
      dispatch(updateGrade(id, data));
     } catch (err) {}
    }
    else {
      try {
        dispatch(studentPassed(id, data));
       } catch (err) {}
    }
  };

  const payFineSubmit = (e) => {
    e.preventDefault();
    const temp = password;
    closeDialog();
    try {
      dispatch(payFine({ number: num, password: temp, id }));
    } catch (err) {}
  };

  const success = (message) => {
    toast.success(message);
  };

  const failure = (error) => {
    toast.error(error);
  };

  const payments = schoolStudent.feePayments
    ? schoolStudent.feePayments.slice(1)
    : [];

  useEffect(() => {
    if (isPaid === true) {
      success("Fee Payment Success");
      dispatch({ type: PAYMENT_SSTUDENT_RESET });
    }

    if (isUpdated === true) {
      success("Grade upgrade success");
      dispatch({ type: UPDATE_GRADE_RESET });
    }

    if (isFined === true) {
      success("Book update success");
      dispatch({ type: FINE_USER_RESET });
    }

    if (error) {
      failure(error);
      dispatch(clearErrors());
    }
    if (paymentError) {
      failure(paymentError);
      dispatch(clearErrors());
    }
    if (fineError) {
      failure(fineError);
      dispatch(clearFineErrors());
    }

    if (schoolStudent) setHostel(schoolStudent.hostel);

    dispatch(getSchoolStudentDetails(id));
  }, [
    dispatch,
    isPaid,
    error,
    paymentError,
    fineError,
    id,
    isUpdated,
    isFined,
  ]);

  return (
    <Fragment>
      {isOpen == 1 && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Payment Details"
        >
          <div>
            <form
              className="loginForm"
              onSubmit={paymentSubmit}
              autocomplete="off"
            >
              <div className="password">
                <label className="custom-label" htmlFor="paidBy">
                  Paid By :
                </label>
                <input
                  id="paidBy"
                  className="form-control filterSelect"
                  type="text"
                  placeholder="Paid By"
                  value={paidBy}
                  onChange={(e) => setPaidBy(e.target.value)}
                />
              </div>
              <div className="password">
                <label className="custom-label" htmlFor="amount">
                  Amount :
                </label>
                <input
                  id="amount"
                  className="form-control filterSelect"
                  type="number"
                  placeholder="amount"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              </div>
              <div className="password">
                <label className="custom-label" htmlFor="receiptNo">
                  Receipt Number :
                </label>
                <input
                  id="receiptNo"
                  className="form-control filterSelect"
                  type="text"
                  placeholder="Receipt Number"
                  value={receiptNo}
                  onChange={(e) => setReceiptNo(e.target.value)}
                />
              </div>
              <div className="password">
                <label className="custom-label" htmlFor="password">
                  Password :
                </label>
                <div className="input-container">
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Admin Password"
                    className="form-control filterSelect"
                    id="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <div
                    className="icon-container"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <FaEyeSlash /> : <FaEye />}
                  </div>
                </div>
              </div>
              <button type="submit" className="btn btn-primary vmax1D">
                PAY FEE
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
      {isOpen == 2 && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Details"
        >
          <div>
            <form
              className="loginForm"
              onSubmit={updateSubmit}
              autocomplete="off"
            >
             {schoolStudent.grade != 12 && <div className="password">
                <label className="custom-label" htmlFor="discount">
                  Discount :
                </label>
                <input
                  id="discount"
                  className="form-control filterSelect"
                  type="number"
                  placeholder="discount"
                  value={discount}
                  onChange={(e) => setDiscount(e.target.value)}
                />
              </div> }
              {schoolStudent.grade != 12 && <div className="checkb">
                Hostel:
                <label className="checkl">
                  <input
                    type="checkbox"
                    checked={hostel}
                    onChange={() => {
                      setHostel(!hostel);
                    }}
                  />
                  Yes
                </label>
                <label className="checkl">
                  <input
                    type="checkbox"
                    checked={!hostel}
                    onChange={() => setHostel(!hostel)}
                  />
                  No
                </label>
              </div> }
              <div className="password">
                <label className="custom-label" htmlFor="password">
                  Password :
                </label>
                <div className="input-container">
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Admin Password"
                    className="form-control filterSelect"
                    id="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <div
                    className="icon-container"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <FaEyeSlash /> : <FaEye />}
                  </div>
                </div>
              </div>

              <button type="submit" className="btn btn-primary vmax1D">
                UPGRADE
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
      {isOpen == 3 && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Admin Password"
        >
          <div>
            <form className="loginForm" onSubmit={payFineSubmit}>
              <div className="password">
                <label className="custom-label" htmlFor="password">
                  Password :
                </label>
                <div className="input-container">
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Admin Password"
                    className="form-control filterSelect"
                    id="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <div
                    className="icon-container"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <FaEyeSlash /> : <FaEye />}
                  </div>
                </div>
              </div>
              <button type="submit" className="btn btn-primary vmax1D">
                PAY
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
      <FeeSidebar />
      <div className="detailsContainer">
        <h2 className="bookName">{schoolStudent.name}</h2>
        <div className="details">
          <span className="prefix">Roll Number : </span>
          <span className="value">{schoolStudent.rollNo}</span>
        </div>
        <div className="details">
          <span className="prefix">Phone Number : </span>
          <span className="value">{schoolStudent.phone}</span>
        </div>
        <div className="details">
          <span className="prefix">Son/Daughter Of : </span>
          <span className="value">
            {schoolStudent.sonOf && schoolStudent.sonOf.name}
          </span>
        </div>
        <div className="details">
          <span className="prefix">parents phone : </span>
          <span className="value">
            {schoolStudent.sonOf && schoolStudent.sonOf.phone}
          </span>
        </div>
        <div className="details">
          <span className="prefix">Stream : </span>
          <span className="value">{schoolStudent.stream}</span>
        </div>
        <div className="details">
          <span className="prefix">Grade : </span>
          <span className="value">{schoolStudent.grade}</span>
        </div>
        <div className="details">
          <span className="prefix">Address : </span>
          <span className="value">{schoolStudent.address}</span>
        </div>
        <div className="details">
          <span className="prefix">Hostel : </span>
          <span className="value">
            {schoolStudent.hostel === true ? "yes" : "no"}
          </span>
        </div>
        <div className="details">
          <span className="prefix">Fee Paid : </span>
          <span className="value">{schoolStudent.feePaid}</span>
        </div>
        <div className="details">
          <span className="prefix">Fee Due : </span>
          <span className="value">{schoolStudent.feeLeft}</span>
        </div>
        <div className="feePayments">
          {payments.map((payment) => {
            return (
              <Link to={`/schoolReceipt/${payment._id}`}>
                <div className="fees">
                  <div className="details">
                    <span className="spanD">Receipt Number : </span>
                    <span>{payment.receiptNo}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Amount : </span>
                    <span className="spanPaid">{payment.amount}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Paid By : </span>
                    <span>{payment.paidBy.toUpperCase()}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Paid On : </span>
                    <span>
                      {payment.paidOn && payment.paidOn.substr(0, 10)}
                    </span>
                  </div>
                  <div className="details">
                    <span className="spanD">Accepted By : </span>
                    <span>{payment.acceptedBy.toUpperCase()}</span>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>
        {schoolStudent.books && schoolStudent.books.length > 0 && (
          <div className="booksToReturn">
            <div className="bookReturnHeading">
              <h4>Books to be returned to library</h4>
            </div>
            {schoolStudent.books.map((book) => {
              return (
                <div className="books">
                  <div className="headingb">{book.bookName.toUpperCase()}</div>
                  <div className="details">
                    <span className="spanD">Number Id : </span>
                    <span>{book.book}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Fine {`(if lost)`} : </span>
                    <span className="spanFine">{book.fine}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Issued By : </span>
                    <span>{book.issuedBy.toUpperCase()}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">Issued On : </span>
                    <span>{book.Date && book.Date.substr(0, 10)}</span>
                  </div>
                  <button
                    className="btn btn-warning fineBtn"
                    onClick={() => {
                      makeNum(book.book);
                      openDialog(3);
                    }}
                  >
                    PAY FINE
                  </button>
                </div>
              );
            })}
          </div>
        )}
        <div className="buttonContainer">
          <button
            className="btn btn-primary btn-lg"
            onClick={() => {
              openDialog(1);
            }}
          >
            Make Payment
          </button>
          {schoolStudent.grade < 12 && (
            <button
              className="btn btn-outline-primary btn-lg"
              onClick={() => {
                openDialog(2);
              }}
            >
              Update to grade {schoolStudent.grade + 1}
            </button>
          )}
          {schoolStudent.grade == 12 && (
            <button
              className="btn btn-outline-primary btn-lg"
              onClick={() => {
                openDialog(2);
              }}
            >
              Student Passed
            </button>
          )}
        </div>
      </div>
    </Fragment>
  );
};

export default SchoolStudentDetails;
