import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  clearErrors,
  getBookDetails,
  updateBook,
} from "../../actions/booksActions";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { UPDATE_BOOK_RESET } from "../../constants/booksConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";

const UpdateBook = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { id } = useParams();
  const { loading, isUpdated, error } = useSelector(
    (state) => state.bookProfile
  );
  const {
    loading: bookLoading,
    error: bookError,
    book,
  } = useSelector((state) => state.bookDetails);

  const [author, setAuthor] = useState();
  const [category, setCategory] = useState();
  const [name, setName] = useState();
  const [cost, setCost] = useState();
  const [yearOfEdition, setYearOfEdition] = useState();
  const [password, setPassword] = useState();
  const [showPassword, setShowPassword] = useState(false);

  const updateSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        author,
        category,
        name,
        cost,
        yearOfEdition,
        password,
      };
      dispatch(updateBook(id, data));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Book Updated Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (!book || (book && book._id !== id)) dispatch(getBookDetails(id));
    else {
      setAuthor(book.author);
      setName(book.name);
      setCost(book.cost);
      setYearOfEdition(book.yearOfEdition);
      setCategory(book.category);
    }
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isUpdated) {
      //  alert.success("Profile updated successfully");
      success();
      navigate(`/book/${book._id}`);
      dispatch({ type: UPDATE_BOOK_RESET });
    }
  }, [dispatch, error, isUpdated, id, book]);

  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <LibrarySidebar />
          <h4>Update Book</h4>
          <form className="loginForm" onSubmit={updateSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                type="text"
                placeholder="name"
                className="form-control filterSelect"
                id="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="Author">
              <label className="custom-label" htmlFor="author">
                Author :
              </label>
              <input
                type="text"
                placeholder="Author"
                className="form-control filterSelect"
                id="author"
                required
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
              />
            </div>
            <div className="Author">
              <label className="custom-label" htmlFor="category">
                Category :
              </label>
              <input
                type="text"
                placeholder="Category"
                className="form-control filterSelect"
                id="category"
                required
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="cost">
                Cost :
              </label>
              <input
                type="number"
                placeholder="cost"
                className="form-control filterSelect"
                id="cost"
                required
                value={cost}
                onChange={(e) => setCost(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="yearOfEdition">
                Year Of Edition :
              </label>
              <input
                type="number"
                placeholder="Year Of Edition"
                className="form-control filterSelect"
                id="yearOfEdition"
                required
                value={yearOfEdition}
                onChange={(e) => setYearOfEdition(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="password">
                Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input
              type="submit"
              value="UPDATE"
              className="btn btn-primary vmax1D"
            />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default UpdateBook;
