import {
  CREATE_BOOK_FAIL,
  CREATE_BOOK_REQUEST,
  CREATE_BOOK_SUCCESS,
  UPDATE_BOOK_FAIL,
  UPDATE_BOOK_REQUEST,
  UPDATE_BOOK_RESET,
  UPDATE_BOOK_SUCCESS,
  ALL_BOOKS_FAIL,
  ALL_BOOKS_REQUEST,
  ALL_BOOKS_SUCCESS,
  BOOK_DETAILS_FAIL,
  BOOK_DETAILS_REQUEST,
  BOOK_DETAILS_SUCCESS,
  WITHDRAW_BOOK_FAIL,
  WITHDRAW_BOOK_REQUEST,
  WITHDRAW_BOOK_RESET,
  WITHDRAW_BOOK_SUCCESS,
  RETURN_BOOK_FAIL,
  RETURN_BOOK_REQUEST,
  RETURN_BOOK_RESET,
  RETURN_BOOK_SUCCESS,
  DELETE_BOOK_FAIL,
  DELETE_BOOK_REQUEST,
  DELETE_BOOK_RESET,
  DELETE_BOOK_SUCCESS,
  CLEAR_ERRORS,
  CREATE_BOOK_EXCEL_FAIL,
  CREATE_BOOK_EXCEL_REQUEST,
  CREATE_BOOK_EXCEL_SUCCESS
} from "../constants/booksConstant";
import axios from "axios";


//create book
export const createBook = (userData) => async (dispatch) => {
  try {
    dispatch({ type: CREATE_BOOK_REQUEST });

  const config = { headers: { "Content-Type": "application/json" } };
    const { data } = await axios.post(`/api/v1/book/new`, userData, config);
    dispatch({ type: CREATE_BOOK_SUCCESS, payload: data });
  } catch (error) {
    dispatch({
      type: CREATE_BOOK_FAIL,
      payload: error.response.data.message,
    });
  }
};

//create from excel
export const createBookFromExcelFile =
(formData) => async (dispatch) => {
  try {
    dispatch({ type: CREATE_BOOK_EXCEL_REQUEST });

    const config = { headers: { "Content-Type": "multipart/form-data" } };
    const { data } = await axios.post(
      `/api/v1/book/create/file`,
      formData,
      config
    );
    dispatch({ type: CREATE_BOOK_EXCEL_SUCCESS, payload: data });
  } catch (error) {
    dispatch({
      type: CREATE_BOOK_EXCEL_FAIL,
      payload: error.response.data.message,
    });
  }
};


  // get All Books
export const getAllBooks = (filterData) => async (dispatch) => {
  try {
    dispatch({ type: ALL_BOOKS_REQUEST, payload:filterData });
    let url = "/api/v1/books";
    if (filterData) {
      const filteredData = Object.fromEntries(
        Object.entries(filterData).filter(([_, value]) => (value !== undefined && value !== ""))
      );

      const queryParams = new URLSearchParams(filteredData).toString();
      if (queryParams) {
        url += `?${queryParams}`;
      }
    }
    const { data } = await axios.get(url);
    console.log(data);

    dispatch({ type: ALL_BOOKS_SUCCESS, payload: data });
  } catch (error) {
    dispatch({ type: ALL_BOOKS_FAIL, payload: error.response.data.message });
  }
};

// get  Book Details
export const getBookDetails = (id) => async (dispatch) => {
  try {
    dispatch({ type: BOOK_DETAILS_REQUEST });
    const { data } = await axios.get(`/api/v1/book/${id}`);

    dispatch({ type: BOOK_DETAILS_SUCCESS, payload: data.book });
  } catch (error) {
    dispatch({ type: BOOK_DETAILS_FAIL, payload: error.response.data.message });
  }
};

// Update Book
export const updateBook = (id, userData) => async (dispatch) => {
  try {
    dispatch({ type: UPDATE_BOOK_REQUEST });

    const config = { headers: { "Content-Type": "application/json" } };

    const { data } = await axios.put(
      `/api/v1/book/${id}`,
      userData,
      config
    );

    dispatch({ type: UPDATE_BOOK_SUCCESS, payload: data.success });
  } catch (error) {
    dispatch({
      type: UPDATE_BOOK_FAIL,
      payload: error.response.data.message,
    });
  }
};



