import React, { Fragment, useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import DataTable from "react-data-table-component";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import "../../../node_modules/bootstrap/dist/css/bootstrap.min.css";
import { Pagination } from "@mui/material";

import "../Books/SearchBook.css";
import {
  clearErrors,
  getAllUsers,
  deleteUser,
} from "../../actions/usersActions";
import { toast } from "react-toastify";
import { DELETE_USER_RESET } from "../../constants/usersConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";
import Loader from "../layout/Loader/Loader";
import { customStyles } from "../../constant";

const SearchUsers = () => {
  const dispatch = useDispatch();

  const { error, users , loading , filterData , totalCount } = useSelector((state) => state.allUsers);

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();
  const [id, setId] = useState();
  const [name, setName] = useState();
  const [phone, setPhone] = useState();

  const [resultsPerPage, setResultsPerPage] = useState(15);
  const [cursor, setCursor] = useState(0);

  const [sortBy, setSortBy] = useState();
  const [sortOrder, setSortOrder] = useState();

  const [yetToReturnSort, setYetToReturnSort] = useState(false);
  const [nameSort, setNameSort] = useState(false);

  const [cursorChange, setCursorChange] = useState(false);
  const [sortChange, setSortChange] = useState(false);
  const [resetFilter, setResetFilter] = useState(false);
  const [resultsPerPageChange, setResultsPerPageChange] = useState(false);
  const [handleFilter, setHandleFilter] = useState(false);

  const failure = (error) => {
    toast.error(error);
  };

  const handlePageChange = (event) => {
    const page = parseInt(event.target.textContent);
    const offset = (page - 1) * resultsPerPage;
    setCursor(offset);
    setCursorChange(true);
  };

  const handleResultsPerPageChange = (event) => {
    setResultsPerPage(event.target.value);
    setCursor(0);
    setResultsPerPageChange(true);
  }

  const sortFunction = (type) => {
    if (type === "name") {
      setNameSort(!nameSort);
      setSortBy("name");
      setSortOrder(nameSort);
    } else if (type === "yetToReturn") {
      setYetToReturnSort(!yetToReturnSort);
      setSortBy("books");
      setSortOrder(yetToReturnSort);
    }
    setSortChange(true);
  };

  {
    users &&
      users.forEach((user, index) => {
        user.num = cursor + index + 1;
      });
  }

  const columns = [
    {
      selector: (row) => <div className="cellData">{row.num}</div>,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("name")}>
          NAME
        </div>
      ),
      selector: (row) => (
        <div>
          <a className="cellLink" href={`/${row.parent}/${row._id}`}>
            <p>{row.name.toUpperCase()}</p>
          </a>
        </div>
      ),
      sortable: true,
      wrap: true,
    },
    {
      name: <div className="headings">PHONE</div>,
      selector: (row) => <div className="cellData">{row.phone}</div>,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("yetToReturn")}>
          YET TO RETURN
        </div>
      ),
      selector: (row) => (
        <div className="cellData">{row.books.length}</div>
      ),
      sortable: true,
      wrap: true,
    },
  ];


  const filterSubmit = (e) => {
    if (e) e.preventDefault();
    const filterParams = {
      name,
      phone,
      sortBy,
      sortOrder,
      limit: resultsPerPage,
      cursor,
    };
    dispatch(getAllUsers(filterParams));
  };


  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (cursorChange) {
      filterSubmit();
      setCursorChange(false);
    } else if (sortChange) {
      filterSubmit();
      setSortChange(false);
    } else if (resetFilter) {
      filterSubmit();
      setResetFilter(false);
    } else if (resultsPerPageChange) {
      filterSubmit();
      setResultsPerPageChange(false);
    } else if (handleFilter) {
      filterSubmit();
      setHandleFilter(false);
    } else if (filterData) {
      dispatch(
        getAllUsers({
          ...filterData,
          limit: filterData.limit ? filterData.limit : 15,
        })
      );
      if (filterData.name) setName(filterData.name);
      if (filterData.phone) setPhone(filterData.phone);
      if (filterData.sortBy) setSortBy(filterData.sortBy);
      if (filterData.sortOrder) setSortOrder(filterData.sortOrder);
      if (filterData.limit) setResultsPerPage(filterData.limit);
      if (filterData.cursor) setCursor(filterData.cursor);
    } else filterSubmit();
  }, [dispatch, error,cursorChange,
    sortChange,
    resetFilter,
    resultsPerPageChange,
    handleFilter]);

  return (
    <Fragment>
    {loading ? (
      <Loader />
    ) : (
      <Fragment>
      <LibrarySidebar />
      <div className="dashboard">
      <div className="filters">
              <div className="nameContainer filterDiv">
                <label htmlFor="nameInput">Name</label>
                <input
                  id="nameInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                  }}
                />
              </div>

              <div className="rollNoContainer filterDiv">
                <label htmlFor="rollNoInput">Phone</label>
                <input
                  id="rollNoInput"
                  type="text"
                  className="form-control rollNoSelect name"
                  placeholder="Subject"
                  value={phone}
                  onChange={(e) => {
                    setPhone(e.target.value);
                  }}
                />
              </div>

              <div className="filterButtons">
                <button
                  className="applyButton"
                  onClick={() => {
                    setCursor(0);
                    setHandleFilter(true);
                  }}
                >
                  APPLY
                </button>
                <button
                  className="resetButton"
                  onClick={() => {
                    setName("");
                    setPhone("");
                    setSortBy("");
                    setSortOrder();
                    setCursor(0);
                    setResetFilter(true);
                  }}
                >
                  RESET
                </button>
              </div>
            </div>
        <div className="productListContainer">
          <DataTable
            columns={columns}
            data={users}
            className="productListTable"
            highlightOnHover={true}
            persistTableHead={true}
            fixedHeader={true}
            striped={true}
            dense={true}
            customStyles={customStyles}
          />
          <div className="pagination">
                <div className="resultsPerPageBox">
                  <span>Results Per Page</span>
                  <select
                    className="form-select"
                    value={resultsPerPage}
                    onChange={handleResultsPerPageChange}
                  >
                    {[5, 15, 25, 50, 100].map((results) => (
                      <option key={results} value={results}>
                        {results} Users
                      </option>
                    ))}
                  </select>
                  <span>
                    Showing {cursor + 1} -{" "}
                    {Math.min(totalCount, cursor + resultsPerPage)} of{" "}
                    {totalCount}
                  </span>
                </div>
                <Pagination
                  count={Math.ceil(totalCount / resultsPerPage)}
                  color="primary"
                  onChange={handlePageChange}
                  page={Math.ceil(cursor / resultsPerPage) + 1}
                  siblingCount={2}
                />
              </div>
        </div>
      </div>
    </Fragment>
    )}
    </Fragment>
  );
};

export default SearchUsers;
