import React, { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "react-toastify";
import { ReactDialogBox } from "react-js-dialog-box";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Books/BookDetails.css";
import MisSidebar from "../layout/Loader/MisSidebar";
import {
  getStaffDetails,
  clearErrors,
  updateStaff,
} from "../../actions/staffActions";
import { payFine } from "../../actions/usersActions.js";
import { UPDATE_STAFF_RESET } from "../../constants/staffConstant";
import { FINE_USER_RESET } from "../../constants/usersConstant.js";

const StaffDetails = () => {
  const dispatch = useDispatch();
  const { id } = useParams();

  const { error, staff } = useSelector((state) => state.staffDetails);
  const { isUpdated, error: updateError } = useSelector(
    (state) => state.staffProfile
  );
  const { isFined, error: fineError } = useSelector(
    (state) => state.userProfile
  );

  const [isOpen, setIsOpen] = useState(0);
  const [password, setPassword] = useState();
  const [num, setNum] = useState();
  const [showPassword, setShowPassword] = useState(false);

  let documents = [];
  if (staff) {
    documents = [
      { name: "Photo", url: staff.photo },
      { name: "Appointment", url: staff.appointment },
      { name: "Highest Degree Certificate", url: staff.pgCertificate },
      { name: "Aadhar Card", url: staff.aadhar },
    ];
  }

  const openDialog = (num) => {
    setIsOpen(num);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(0);
  };

  const makeNum = (numb) => {
    setNum(numb);
  };

  const payFineSubmit = (e) => {
    e.preventDefault();
    const temp = password;
    closeDialog();
    try {
      dispatch(payFine({ number: num, password: temp, id }));
    } catch (err) {}
  };

  const reduceSubmit = (e) => {
    e.preventDefault();
    const temp = password;
    closeDialog();
    const data = {
      password: temp,
      leavesUsed: staff.leavesUsed + 1,
    };
    try {
      dispatch(updateStaff(id, data));
    } catch (err) {}
  };

  const success = (message) => {
    toast.success(message);
  };
  const failure = (error) => {
    toast.error(error);
  };

  const salaryLeft = (dateString, salary) => {
    const date1 = new Date(dateString);
    const date2 = new Date(Date.now());

    // Calculate the difference in months
    const monthsDifference =
      (date2.getFullYear() - date1.getFullYear()) * 12 +
      (date2.getMonth() - date1.getMonth()) +
      (date2.getDate() < date1.getDate() && date2.getMonth() > date1.getMonth()
        ? -1
        : 0);

    const dateDiff = date2.getDate() - date1.getDate();
    const days = dateDiff < 0 ? dateDiff + 30 : dateDiff;
    return monthsDifference * salary + days * (salary / 30);
  };

  const moneyToDeduct = staff.deductionLeaves * Math.round(staff.salary / 30);

  useEffect(() => {
    if (error || updateError || fineError) {
      failure(error ? error : updateError ? updateError : fineError);
      dispatch(clearErrors());
    }
    if (isUpdated) {
      success("Leaved Added Successfully");
      dispatch({ type: UPDATE_STAFF_RESET });
    }
    if (isFined) {
      success("updated successfully");
      dispatch({ type: FINE_USER_RESET });
    }
    dispatch(getStaffDetails(id));
  }, [dispatch, isUpdated, id, isFined]);

  return (
    <>
      {isOpen == 1 && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Admin Password"
        >
          <div>
            <form className="loginForm" onSubmit={reduceSubmit}>
              <div className="password">
                <label className="custom-label" htmlFor="password">
                  Password :
                </label>
                <input
                  id="password"
                  className="form-control filterSelect"
                  type="password"
                  placeholder="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                ></input>
              </div>
              <button type="submit" className="btn btn-warning vmax1D">
                REDUCE
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
      {isOpen == 2 && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Admin Password"
        >
          <div>
            <form className="loginForm" onSubmit={payFineSubmit}>
              <div className="password">
                <label className="custom-label" htmlFor="password">
                  Password :
                </label>
                <div className="input-container">
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Admin Password"
                    className="form-control filterSelect"
                    id="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                  />
                  <div
                    className="icon-container"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <FaEyeSlash /> : <FaEye />}
                  </div>
                </div>
              </div>
              <button type="submit" className="btn btn-primary vmax1D">
                PAY
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
      <MisSidebar />
      <div className="detailsContainer">
        <h2 className="bookName">{staff.name}</h2>

        <div className="details">
          <span className="prefix">Phone Number : </span>
          <span className="value">{staff.phone}</span>
        </div>

        <div className="details">
          <span className="prefix">Salary : </span>
          <span className="value">{staff.salary}</span>
        </div>

        <div className="details">
          <span className="prefix">Qualification : </span>
          <span className="value">{staff.qualification}</span>
        </div>

        <div className="details">
          <span className="prefix">Designation : </span>
          <span className="value">{staff.designation}</span>
        </div>

        <div className="details">
          <span className="prefix">Subject : </span>
          <span className="value">{staff.subject}</span>
        </div>

        <div className="details">
          <span className="prefix">leaves allowed : </span>
          <span className="value">{staff.leavesAllowed}</span>
        </div>

        <div className="details">
          <span className="prefix">leaves used : </span>
          <span className="value">{staff.leavesUsed}</span>
        </div>

        <div className="details">
          <span className="prefix">leaves remaining : </span>
          <span className="value">
            {staff.leavesAllowed - staff.leavesUsed}
          </span>
        </div>

        <div className="details">
          <span className="prefix">salary cleared till date : </span>
          <span className="value">{staff.lastMonthPaid}</span>
        </div>

        <div className="details">
          <span className="prefix">Salary yet to be paid : </span>
          <span className="value">
            {Math.ceil(
              salaryLeft(staff.lastMonthPaid, staff.salary) - moneyToDeduct
            )}
          </span>
        </div>

        <div className="details">
          {documents.map((document, index) => (
            <div key={index} className="documentsDiv">
              <span className="prefix">{document.name} :</span>
              <a
                href={document.url}
                className="documentLinks"
                target="_blank"
                rel="noopener noreferrer"
              >
                <button className="btn btn-outline-primary documentBtn">
                  VIEW
                </button>
              </a>
            </div>
          ))}
        </div>
        <button
          className="btn btn-danger vmax1D wd20 mrgnlft30"
          onClick={() => {
            openDialog(1);
          }}
        >
          REDUCE ONE LEAVE
        </button>
        {staff.books && staff.books.length > 0 && (
          <div className="booksToReturn">
            <div className="bookReturnHeading">
              <h4>Books to be returned to library</h4>
            </div>
            {staff.books.map((book) => {
              return (
                <div className="books">
                  <div className="headingb">{book.bookName.toUpperCase()}</div>
                  <div className="details">
                    <span className="spanD">NUMBER ID : </span>
                    <span>{book.book}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">FINE : </span>
                    <span className="spanFine">{book.fine}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">ISSUED BY : </span>
                    <span>{book.issuedBy.toUpperCase()}</span>
                  </div>
                  <div className="details">
                    <span className="spanD">ISSUED ON : </span>
                    <span>{book.Date && book.Date.substr(0, 10)}</span>
                  </div>
                  <button
                    className="btn btn-warning fineBtn"
                    onClick={() => {
                      makeNum(book.book);
                      openDialog(2);
                    }}
                  >
                    PAY FINE
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </>
  );
};

export default StaffDetails;
