import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { clearErrors, returnBook } from "../../actions/booksActions";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { RETURN_BOOK_RESET } from "../../constants/booksConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";

const ReturnBook = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { loading, isReturned, error } = useSelector(
    (state) => state.bookProfile
  );

  const [bookNumber, setBookNumber] = useState();
  const [returnerName, setReturnerName] = useState();
  const [returnerPhone,setReturnerPhone] = useState();
  const [password, setPassword] = useState();
  const [showPassword, setShowPassword] = useState(false);

  const returnSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        number: bookNumber,
        returnerName: returnerName.toLowerCase(),
        returnerPhone,
        password,
      };
      dispatch(returnBook(data));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Book Return Successful");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isReturned) {
      //  alert.success("Profile updated successfully");
      success();
      navigate("/library");
      dispatch({ type: RETURN_BOOK_RESET });
    }
  }, [dispatch, error, isReturned]);

  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <LibrarySidebar/>
          <h4>Return Book</h4>
          <form className="loginForm" onSubmit={returnSubmit} autocomplete="off">
            <div className="loginPhone">
              <label htmlFor="bookNumber" className="custom-label">Book Number :</label>
              <input
                type="text"
                placeholder="Book Number"
                id="bookNumber"
                className="form-control filterSelect"
                required
                value={bookNumber}
                onChange={(e) => setBookNumber(e.target.value)}
              />
            </div>
            <div className="name">
              <label htmlFor="returnerName" className="custom-label">Returner Name :</label>
              <input
                type="text"
                placeholder="Returner Name"
                className="form-control filterSelect"
                id="returnerName"
                required
                value={returnerName}
                onChange={(e) => setReturnerName(e.target.value)}
              />
            </div>
            <div className="name">
              <label htmlFor="returnerPhone" className="custom-label">Returner Phone :</label>
              <input
                type="text"
                placeholder="Returner Phone Number"
                className="form-control filterSelect"
                id="returnerPhone"
                required
                value={returnerPhone}
                onChange={(e) => setReturnerPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label htmlFor="password" className="custom-label">Password :</label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input type="submit" value="Return" className="btn btn-primary vmax1D" />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default ReturnBook;
