import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "react-toastify";

import "../Admin/UpdateProfile.css";
import InventorySidebar from "../layout/Loader/InventorySidebar";
import {
  clearErrors,
  createItem,
  createItemFromExcelFile,
} from "../../actions/inventoryActions";
import { CREATE_ITEM_RESET } from "../../constants/inventoryConstant";

const CreateItem = () => {
  const dispatch = useDispatch();
  // const navigate = useNavigate();

  const { loading, isCreated, error } = useSelector((state) => state.newItem);

  const strDate = new Date();
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowFormatted = tomorrow.toISOString().split("T")[0];

  const [name, setName] = useState();
  const [lab, setLab] = useState();
  const [cost, setCost] = useState();
  const [stock, setStock] = useState();
  const [damaged, setDamaged] = useState();
  const [dateOfPurchase, setDateOfPurchase] = useState(strDate);
  const [file, setFile] = useState(null);

  const labs = [
    "BOTANY",
    "ZOOLOGY",
    "PHYSICS",
    "CHEMISTRY",
    "IT",
    "MESS",
    "INFRASTRUCTURE",
  ];

  const createSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        name,
        lab,
        cost,
        stock,
        damaged,
        dateOfPurchase,
      };
      dispatch(createItem(data));
    } catch (err) {}
  };

  const onFileUpload = (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("file", file);
      dispatch(createItemFromExcelFile(formData));
    } catch (err) {
      console.log(err);
    }
  };

  const success = () => {
    toast.success("Item Created Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isCreated) {
      //  alert.success("Profile updated successfully");
      success();
      dispatch({ type: CREATE_ITEM_RESET });
    }
  }, [dispatch, error, isCreated]);

  return (
    <div className="cardUPR">
      <InventorySidebar />
      <div className="createHeaders">
        <p>Create New Item</p>
        <p className="pushRight">Upload Excel File</p>
      </div>
      <div className="createDivsContainer">
        <div className="createSingleContainer">
          <form className="loginForm" onSubmit={createSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                type="text"
                placeholder="name"
                className="form-control filterSelect"
                id="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="cost">
                Cost :
              </label>
              <input
                type="number"
                placeholder="cost"
                className="form-control filterSelect"
                id="cost"
                required
                value={cost}
                onChange={(e) => setCost(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="stock">
                Initial Stock :
              </label>
              <input
                type="number"
                placeholder="initial stock"
                className="form-control filterSelect"
                id="stock"
                required
                value={stock}
                onChange={(e) => setStock(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="damaged">
                Damaged Stock :
              </label>
              <input
                type="number"
                placeholder="damaged"
                className="form-control filterSelect"
                id="damaged"
                required
                value={damaged}
                onChange={(e) => setDamaged(e.target.value)}
              />
            </div>
            <div>
              <label className="custom-label" htmlFor="lab">
                Select Lab :
              </label>
              <select
                onChange={(e) => setLab(e.target.value)}
                className="form-select"
                id="lab"
              >
                <option value="">{lab ? lab : "Select Lab"}</option>
                {labs.map((cate) => (
                  <option key={cate} value={cate}>
                    {cate}
                  </option>
                ))}
              </select>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="date">
                Date of Purchase :
              </label>
              <input
                type="date"
                placeholder="date of purchase"
                className="form-control filterSelect"
                id="date"
                required
                value={dateOfPurchase}
                onChange={(e) => setDateOfPurchase(e.target.value)}
                max={tomorrowFormatted}
              />
            </div>
            <input
              type="submit"
              value="CREATE"
              className="btn btn-primary vmax1D"
              disabled={loading}
            />
          </form>
        </div>
        <div className="createMultipleContainer">
          <div className="password">
            <label className="custom-label" htmlFor="itemsExcel">
              Choose Excel File With Items Data :
            </label>
            <input
              id="itemsExcel"
              className="form-control filterSelect vmax1D"
              type="file"
              accept="application/xlsx"
              onChange={(e) => setFile(e.target.files[0])}
            />
          </div>

          <button
            onClick={onFileUpload}
            disabled={loading}
            className="btn btn-primary"
          >
            UPLOAD
          </button>
        </div>
      </div>
    </div>
  );
};
export default CreateItem;
