import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "react-toastify";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import FeeSidebar from "../layout/Loader/FeeSidebar";
import {
  clearErrors,
  createSchoolStudent,
  createScoolStudentFromExcelFile,
} from "../../actions/schoolStudentActions";
import { CREATE_SSTUDENT_RESET } from "../../constants/schoolStudentConstant";

const CreateSchoolStudent = () => {
  const dispatch = useDispatch();
  // const navigate = useNavigate();

  const { loading, isCreated, error } = useSelector(
    (state) => state.newSchoolStudent
  );

  const [sonOf, setSonOf] = useState();
  const [name, setName] = useState();
  const [rollNo, setRollNo] = useState();
  const [phone, setPhone] = useState();
  const [parentsPhone, setParentsPhone] = useState();
  const [stream, setStream] = useState();
  const [grade, setGrade] = useState();
  const [discounted, setDiscounted] = useState();
  const [address, setAddress] = useState();
  const [hostel, setHostel] = useState(false);
  const [file, setFile] = useState(null);

  const createSubmit = (e) => {
    e.preventDefault();
    try {
      const temp = {
        sonOf: {
          name: sonOf,
          phone: parentsPhone,
        },
      };
      const data = {
        ...temp,
        name,
        rollNo,
        phone,
        stream,
        grade,
        address,
        hostel,
        discounted,
      };
      dispatch(createSchoolStudent(data));
    } catch (err) {}
  };

  const onFileUpload = (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("file", file);
      dispatch(createScoolStudentFromExcelFile(formData));
    } catch (err) {
      console.log(err);
    }
  };

  const success = () => {
    toast.success("Student Created Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isCreated) {
      //  alert.success("Profile updated successfully");
      success();
      dispatch({ type: CREATE_SSTUDENT_RESET });
    }
  }, [dispatch, error, isCreated]);

  return (
    <div className="cardUPR">
      <FeeSidebar />
      <div className="createHeaders">
        <p>Create New School Student</p>
        <p>Upload Excel File</p>
      </div>
      <div className="createDivsContainer">
        <div className="createSingleContainer">
          <form className="loginForm" onSubmit={createSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                type="text"
                placeholder="name"
                className="form-control filterSelect"
                id="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="Author">
              <label className="custom-label" htmlFor="parentName">
                Son/Daughter of :
              </label>
              <input
                type="text"
                placeholder="son/daughter Of"
                className="form-control filterSelect"
                id="parentName"
                required
                value={sonOf}
                onChange={(e) => setSonOf(e.target.value)}
              ></input>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="studentPhone">
                Student's Phone :
              </label>
              <input
                type="text"
                placeholder="student Phone Number"
                className="form-control filterSelect"
                id="studentPhone"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="parentPhone">
                Parent's Phone :
              </label>
              <input
                type="text"
                placeholder="parent's phone"
                className="form-control filterSelect"
                id="parentPhone"
                required
                value={parentsPhone}
                onChange={(e) => setParentsPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="address">
                Address :
              </label>
              <input
                type="text"
                placeholder="address"
                className="form-control filterSelect"
                id="address"
                required
                value={address}
                onChange={(e) => setAddress(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="stream">
                Stream :
              </label>
              <input
                type="text"
                placeholder="stream"
                className="form-control filterSelect"
                id="stream"
                required
                value={stream}
                onChange={(e) => setStream(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="grade">
                Grade :
              </label>
              <input
                type="number"
                placeholder="grade"
                className="form-control filterSelect"
                id="grade"
                required
                value={grade}
                onChange={(e) => setGrade(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="rollNo">
                Roll No. :
              </label>
              <input
                type="text"
                placeholder="roll number"
                className="form-control filterSelect"
                id="rollNo"
                required
                value={rollNo}
                onChange={(e) => setRollNo(e.target.value)}
              />
            </div>
            <div className="checkb">
              Hostel:
              <label className="checkl">
                <input
                  type="checkbox"
                  checked={hostel}
                  onChange={() => {
                    setHostel(!hostel);
                  }}
                />
                Yes
              </label>
              <label className="checkl">
                <input
                  type="checkbox"
                  checked={!hostel}
                  onChange={() => setHostel(!hostel)}
                />
                No
              </label>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="discount">
                Discount :
              </label>
              <input
                type="number"
                placeholder="discounted amount in rupees"
                className="form-control filterSelect"
                id="discount"
                required
                value={discounted}
                onChange={(e) => setDiscounted(e.target.value)}
              />
            </div>
            <input
              type="submit"
              value="CREATE"
              className="btn btn-primary vmax1D"
              disabled={loading}
            />
          </form>
        </div>
        <div className="createMultipleContainer">
          <div className="password">
            <label className="custom-label" htmlFor="schoolStudentExcel">
              Choose Excel File With School Students Data :
            </label>
            <input
              id="schoolStudentExcel"
              className="form-control filterSelect vmax1D"
              type="file"
              accept="application/xlsx"
              onChange={(e) => setFile(e.target.files[0])}
            />
          </div>

          <button
            onClick={onFileUpload}
            disabled={loading}
            className="btn btn-primary"
          >
            UPLOAD
          </button>
        </div>
      </div>
    </div>
  );
};
export default CreateSchoolStudent;
