import React, { Fragment, useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import DataTable from "react-data-table-component";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import "../../../node_modules/bootstrap/dist/css/bootstrap.min.css";
import { Pagination } from "@mui/material";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "./SearchBook.css";
import {
  clearErrors,
  getAllBooks,
  deleteBook,
} from "../../actions/booksActions";
import { toast } from "react-toastify";
import { DELETE_BOOK_RESET } from "../../constants/booksConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";
import Loader from "../layout/Loader/Loader";
import { customStyles } from "../../constant";

const SearchBook = () => {
  const dispatch = useDispatch();

  const { error, books, filterData, loading, totalCount } = useSelector(
    (state) => state.allBooks
  );

  const {
    error: deleteError,
    isDeleted,
    loading: deleteLoading,
  } = useSelector((state) => state.bookProfile);

  const [showPassword, setShowPassword] = useState(false);

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();
  const [id, setId] = useState();
  const [number, setNumber] = useState();
  const [name, setName] = useState();
  const [author, setAuthor] = useState();
  const [category, setCategory] = useState();
  const [bookWith, setBookWith] = useState();

  const [resultsPerPage, setResultsPerPage] = useState(15);
  const [cursor, setCursor] = useState(0);

  const [sortBy, setSortBy] = useState();
  const [sortOrder, setSortOrder] = useState();

  const [numberSort, setNumberSort] = useState(false);
  const [nameSort, setNameSort] = useState(false);
  const [costSort, setCostSort] = useState(false);
  const [yearOfEditionSort, setYearOfEditionSort] = useState(false);

  const [cursorChange, setCursorChange] = useState(false);
  const [sortChange, setSortChange] = useState(false);
  const [resetFilter, setResetFilter] = useState(false);
  const [resultsPerPageChange, setResultsPerPageChange] = useState(false);
  const [handleFilter, setHandleFilter] = useState(false);

  const openDialog = () => {
    setIsOpen(true);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(false);
  };

  const makeId = (id) => {
    setId(id);
  };

  const deleteSubmit = () => {
    const temp = password;
    closeDialog();
    dispatch(deleteBook(id, temp));
  };

  const successDelete = () => {
    toast.success("Book Deleted Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };

  const handlePageChange = (event) => {
    const page = parseInt(event.target.textContent);
    const offset = (page - 1) * resultsPerPage;
    setCursor(offset);
    setCursorChange(true);
  };

  const handleResultsPerPageChange = (event) => {
    setResultsPerPage(event.target.value);
    setCursor(0);
    setResultsPerPageChange(true);
  };

  const sortFunction = (type) => {
    if (type === "number") {
      setNumberSort(!numberSort);
      setSortBy("number");
      setSortOrder(numberSort);
    } else if (type === "name") {
      setNameSort(!nameSort);
      setSortBy("name");
      setSortOrder(nameSort);
    } else if (type === "cost") {
      setCostSort(!costSort);
      setSortBy("cost");
      setSortOrder(costSort);
    } else if (type === "yearOfEdition") {
      setYearOfEditionSort(!yearOfEditionSort);
      setSortBy("yearOfEdition");
      setSortOrder(yearOfEditionSort);
    }
    setSortChange(true);
  };

  {
    books &&
      books.forEach((staff, index) => {
        staff.num = cursor + index + 1;
      });
  }

  const columns = [
    {
      selector: (row) => <div className="cellData">{row.num}</div>,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("number")}>
          NUMBER ID
        </div>
      ),
      selector: (row) => <div className="cellData">{row.number}</div>,
      sortable: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("name")}>
          NAME
        </div>
      ),
      selector: (row) => (
        <div>
          <a className="cellLink" href={`/book/${row._id}`}>
            <p>{row.name.toUpperCase()}</p>
          </a>
        </div>
      ),
      sortable: true,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("author")}>
          AUTHOR
        </div>
      ),
      selector: (row) => (
        <div className="cellData">{row.author.toUpperCase()}</div>
      ),
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("category")}>
          CATEGORY
        </div>
      ),
      selector: (row) => (
        <div className="cellData">{row.category.toUpperCase()}</div>
      ),
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("cost")}>
          PRICE
        </div>
      ),
      selector: (row) => <div className="cellData">{row.cost}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: <div className="headings">BOOK WITH</div>,
      selector: (row) => (
        <div
          className={`cellData ${
            row.bookWith === "library" ? "greenClass" : "redClass"
          }`}
        >
          {row.bookWith.toUpperCase()}
        </div>
      ),
      wrap: true,
    },
    {
      name: <div className="headings">LAST ACCEPTED BY</div>,
      selector: (row) => (
        <div className="cellData">
          {row.lastAcceptor && row.lastAcceptor.toUpperCase()}
        </div>
      ),
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("yearOfEdition")}>
          Y O ED.
        </div>
      ),
      selector: (row) => <div className="cellData">{row.yearOfEdition}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: "",
      cell: (row) => (
        <a className="rlinks" href={`/update/book/${row._id}`}>
          <button className="butn">EDIT</button>
        </a>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            openDialog();
            makeId(row._id);
          }}
          className="delBtn"
        >
          DELETE
        </button>
      ),
    },
  ];

  const filterSubmit = (e) => {
    if (e) e.preventDefault();
    const filterParams = {
      name,
      number,
      author,
      category,
      bookWith,
      sortBy,
      sortOrder,
      limit: resultsPerPage,
      cursor,
    };
    dispatch(getAllBooks(filterParams));
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (deleteError) {
      failure(deleteError);
      dispatch(clearErrors());
    }

    if (isDeleted === true) {
      successDelete();
      dispatch({ type: DELETE_BOOK_RESET });
    }

    if (cursorChange) {
      filterSubmit();
      setCursorChange(false);
    } else if (sortChange) {
      filterSubmit();
      setSortChange(false);
    } else if (resetFilter) {
      filterSubmit();
      setResetFilter(false);
    } else if (resultsPerPageChange) {
      filterSubmit();
      setResultsPerPageChange(false);
    } else if (handleFilter) {
      filterSubmit();
      setHandleFilter(false);
    } else if (filterData) {
      dispatch(
        getAllBooks({
          ...filterData,
          limit: filterData.limit ? filterData.limit : 15,
        })
      );
      if (filterData.name) setName(filterData.name);
      if (filterData.number) setNumber(filterData.number);
      if (filterData.author) setAuthor(filterData.author);
      if (filterData.bookWith) setBookWith(filterData.bookWith);
      if (filterData.category) setCategory(filterData.category);
      if (filterData.sortBy) setSortBy(filterData.sortBy);
      if (filterData.sortOrder) setSortOrder(filterData.sortOrder);
      if (filterData.limit) setResultsPerPage(filterData.limit);
      if (filterData.cursor) setCursor(filterData.cursor);
    } else filterSubmit();
    console.log(filterData, books);
  }, [
    dispatch,
    error,
    deleteError,
    isDeleted,
    cursorChange,
    sortChange,
    resetFilter,
    resultsPerPageChange,
    handleFilter,
  ]);

  return (
    <Fragment>
      {loading || deleteLoading ? (
        <Loader />
      ) : (
        <Fragment>
          {isOpen && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Admin Password"
            >
              <div>
                <form className="loginForm" onSubmit={deleteSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>
                  <button type="submit" className="btn btn-danger vmax1D">
                    DELETE
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          <LibrarySidebar />
          <div className="dashboard">
            <div className="filters">
              <div className="nameContainer filterDiv">
                <label htmlFor="nameInput">Name</label>
                <input
                  id="nameInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                  }}
                />
              </div>

              <div className="numberContainer filterDiv">
                <label htmlFor="numberInput">Number Id</label>
                <input
                  id="numberInput"
                  type="number"
                  className="form-control numberSelect name"
                  placeholder="Number Id"
                  value={number}
                  onChange={(e) => {
                    setNumber(e.target.value);
                  }}
                />
              </div>

              <div className="nameContainer filterDiv">
                <label htmlFor="authorInput">Author</label>
                <input
                  id="authorInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Author"
                  value={author}
                  onChange={(e) => {
                    setAuthor(e.target.value);
                  }}
                />
              </div>

              <div className="nameContainer filterDiv">
                <label htmlFor="categoryInput">Category</label>
                <input
                  id="categoryInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Category"
                  value={category}
                  onChange={(e) => {
                    setCategory(e.target.value);
                  }}
                />
              </div>

              <div className="streamContainer filterDiv largeContainer">
                <label htmlFor="bookWithSelect">Book With</label>
                <select
                  id="bookWithSelect"
                  className="form-select streamSelect batch"
                  value={bookWith}
                  onChange={(e) => {
                    setBookWith(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {["LIBRARY", "OTHERS"].map((bookWith) => (
                    <option key={bookWith} value={bookWith}>
                      {bookWith}
                    </option>
                  ))}
                </select>
              </div>

              <div className="filterButtons">
                <button
                  className="applyButton"
                  onClick={() => {
                    setCursor(0);
                    setHandleFilter(true);
                  }}
                >
                  APPLY
                </button>
                <button
                  className="resetButton"
                  onClick={() => {
                    setName("");
                    setNumber("");
                    setAuthor("");
                    setCategory("");
                    setBookWith("");
                    setSortBy("");
                    setSortOrder();
                    setCursor(0);
                    setResetFilter(true);
                  }}
                >
                  RESET
                </button>
              </div>
            </div>
            <div className="productListContainer">
              <DataTable
                columns={columns}
                data={books}
                className="productListTable"
                highlightOnHover={true}
                persistTableHead={true}
                fixedHeader={true}
                striped={true}
                dense={true}
                customStyles={customStyles}
              />
              <div className="pagination">
                <div className="resultsPerPageBox">
                  <span>Results Per Page</span>
                  <select
                    className="form-select"
                    value={resultsPerPage}
                    onChange={handleResultsPerPageChange}
                  >
                    {[5, 15, 25, 50, 100].map((results) => (
                      <option key={results} value={results}>
                        {results} Books
                      </option>
                    ))}
                  </select>
                  <span>
                    Showing {cursor + 1} -{" "}
                    {Math.min(totalCount, cursor + resultsPerPage)} of{" "}
                    {totalCount}
                  </span>
                </div>
                <Pagination
                  count={Math.ceil(totalCount / resultsPerPage)}
                  color="primary"
                  onChange={handlePageChange}
                  page={Math.ceil(cursor / resultsPerPage) + 1}
                  siblingCount={2}
                />
              </div>
            </div>
          </div>
        </Fragment>
      )}
    </Fragment>
  );
};

export default SearchBook;
