import {
  ALL_USERS_FAIL,
  ALL_USERS_REQUEST,
  ALL_USERS_SUCCESS,
  CLEAR_ERRORS,
  CREATE_USER_FAIL,
  CREATE_USER_REQUEST,
  CREATE_USER_SUCCESS,
  UPDATE_USER_FAIL,
  UPDATE_USER_REQUEST,
  UPDATE_USER_SUCCESS,
  USER_DETAILS_FAIL,
  USER_DETAILS_REQUEST,
  USER_DETAILS_SUCCESS,
  DELETE_USER_FAIL,
  DELETE_USER_REQUEST,
  DELETE_USER_SUCCESS,
  FINE_USER_REQUEST,
  FINE_USER_SUCCESS,
  FINE_USER_FAIL,
} from "../constants/usersConstant";
import axios from "axios";

// get All Users
export const getAllUsers =
  (filterData) =>
  async (dispatch) => {
    try {
      dispatch({ type: ALL_USERS_REQUEST , payload:filterData});
      let url = "/api/v1/users";
      if (filterData) {
        const filteredData = Object.fromEntries(
          Object.entries(filterData).filter(([_, value]) => (value !== undefined && value !== ""))
        );
  
        const queryParams = new URLSearchParams(filteredData).toString();
        if (queryParams) {
          url += `?${queryParams}`;
        }
      }
      const { data } = await axios.get(url);

      dispatch({ type: ALL_USERS_SUCCESS, payload: data });
    } catch (error) {
      dispatch({ type: ALL_USERS_FAIL, payload: error });
    }
  };


// fine user
export const payFine = (userData) => async(dispatch) =>{
  try{
    dispatch({type:FINE_USER_REQUEST});
    const config = { headers: { "Content-Type": "application/json" } };
    const {data} = await axios.put("/api/v1/user/payfine",userData,config);
    console.log(data);

    dispatch({type:FINE_USER_SUCCESS,payload:data.success});
  }
  catch(error){
    dispatch({
      type: FINE_USER_FAIL,
      payload: error.response.data.message,
    });
  }
};


// to clear errors
export const clearErrors = () => async (dispatch) => {
  dispatch({
    type: CLEAR_ERRORS,
  });
};
