import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  createBook,
  clearErrors,
  createBookFromExcelFile,
} from "../../actions/booksActions";
import { toast } from "react-toastify";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { CREATE_BOOK_RESET } from "../../constants/booksConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";

const CreateBook = () => {
  const dispatch = useDispatch();

  const { loading, isCreated, error, book } = useSelector(
    (state) => state.newBook
  );

  const [author, setAuthor] = useState();
  const [name, setName] = useState();
  const [number, setNumber] = useState();
  const [cost, setCost] = useState();
  const [yearOfEdition, setYearOfEdition] = useState();
  const [category, setCategory] = useState();
  const [file, setFile] = useState(null);

  const createSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        author,
        name,
        number,
        category,
        cost: cost ? cost : 500,
        yearOfEdition: yearOfEdition ? yearOfEdition : 0,
      };
      dispatch(createBook(data));
    } catch (err) {}
  };

  const onFileUpload = (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("file", file);
      dispatch(createBookFromExcelFile(formData));
    } catch (err) {
      console.log(err);
    }
  };

  const success = () => {
    toast.success("Book Created Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isCreated) {
      //  alert.success("Profile updated successfully");
      success();
      dispatch({ type: CREATE_BOOK_RESET });
    }
  }, [dispatch, error, isCreated]);

  return (
    <div className="cardUPR">
      <LibrarySidebar />
      <div className="createHeaders">
        <p>Create New Book</p>
        <p className="pushRight">Upload Excel File</p>
      </div>
      <div className="createDivsContainer">
        <div className="createSingleContainer">
          <form className="loginForm" onSubmit={createSubmit}>
            <div className="loginPhone">
              <label htmlFor="bookName" className="custom-label">
                Name :
              </label>
              <input
                type="text"
                placeholder="name"
                id="bookName"
                className="form-control filterSelect"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="Author">
              <label htmlFor="bookAuthor" className="custom-label">
                Author :
              </label>
              <input
                type="text"
                placeholder="Author"
                id="bookAuthor"
                className="form-control filterSelect"
                required
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
              ></input>
            </div>
            <div className="password">
              <label htmlFor="bookNumber" className="custom-label">
                Book Number :
              </label>
              <input
                type="text"
                placeholder="book Number"
                id="bookNumber"
                className="form-control filterSelect"
                required
                value={number}
                onChange={(e) => setNumber(e.target.value)}
              />
            </div>
            <div className="password">
              <label htmlFor="bookCategory" className="custom-label">
                Category :
              </label>
              <input
                type="text"
                placeholder="Category"
                id="bookCategory"
                className="form-control filterSelect"
                required
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              />
            </div>
            <div className="password">
              <label htmlFor="bookCost" className="custom-label">
                Cost :
              </label>
              <input
                type="number"
                placeholder="cost"
                id="bookCost"
                className="form-control filterSelect"
                required
                value={cost}
                onChange={(e) => setCost(e.target.value)}
              />
            </div>
            <div className="password">
              <label htmlFor="bookYOE" className="custom-label">
                Year Of Edition :
              </label>
              <input
                type="number"
                placeholder="Year Of Edition"
                id="bookYOE"
                className="form-control filterSelect"
                required
                value={yearOfEdition}
                onChange={(e) => setYearOfEdition(e.target.value)}
              />
            </div>
            <input
              type="submit"
              value="CREATE"
              className="btn btn-primary vmax1D"
              disabled={loading}
            />
          </form>
        </div>
        <div className="createMultipleContainer">
          <div className="password">
            <label className="custom-label" htmlFor="booksExcel">
              Choose Excel File With Books Data :
            </label>
            <input
              id="booksExcel"
              className="form-control filterSelect vmax1D"
              type="file"
              accept="application/xlsx"
              onChange={(e) => setFile(e.target.files[0])}
            />
          </div>

          <button
            onClick={onFileUpload}
            disabled={loading}
            className="btn btn-primary"
          >
            UPLOAD
          </button>
        </div>
      </div>
    </div>
  );
};
export default CreateBook;
