import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import {
  clearErrors,
  getSchoolStudentDetails,
  updateSchoolStudent,
} from "../../actions/schoolStudentActions";
import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { UPDATE_SSTUDENT_RESET } from "../../constants/schoolStudentConstant";
import FeeSidebar from "../layout/Loader/FeeSidebar";

const UpdateSchoolStudent = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { id } = useParams();

  const { loading, isUpdated, error } = useSelector(
    (state) => state.schoolStudentProfile
  );
  const {
    loading: studentLoading,
    error: studentError,
    schoolStudent,
  } = useSelector((state) => state.schoolStudentDetails);

  const [sonOf, setSonOf] = useState();
  const [name, setName] = useState();
  const [rollNo, setRollNo] = useState();
  const [phone, setPhone] = useState();
  const [parentsPhone, setParentsPhone] = useState();
  const [stream, setStream] = useState();
  const [address, setAddress] = useState();
  const [password, setPassword] = useState();
  const [hostel, setHostel] = useState();

  const [showPassword, setShowPassword] = useState(false);

  const updateSubmit = (e) => {
    e.preventDefault();
    try {
      const temp = {
        sonOf: {
          name: sonOf,
          phone: parentsPhone,
        },
      };
      const data = {
        ...temp,
        name,
        rollNo,
        phone,
        stream,
        address,
        password,
        hostel,
        grade: schoolStudent.grade,
      };
      dispatch(updateSchoolStudent(id, data));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Student Updated Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (!schoolStudent || (schoolStudent && schoolStudent._id !== id))
      dispatch(getSchoolStudentDetails(id));
    else {
      setName(schoolStudent.name);
      setPhone(schoolStudent.phone);
      setSonOf(schoolStudent.sonOf.name);
      setRollNo(schoolStudent.rollNo);
      setParentsPhone(schoolStudent.sonOf.phone);
      setStream(schoolStudent.stream);
      setAddress(schoolStudent.address);
      setHostel(schoolStudent.hostel);
    }
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }
    if (studentError) {
      failure(studentError);
      dispatch(clearErrors());
    }
    if (isUpdated) {
      //  alert.success("Profile updated successfully");
      success();
      navigate(`/schoolStudent/${schoolStudent._id}`);
      dispatch({ type: UPDATE_SSTUDENT_RESET });
    }
  }, [dispatch, error, isUpdated, id, schoolStudent]);

  return (
    <Fragment>
      {loading || studentLoading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <FeeSidebar />
          <h4>Update Student</h4>
          <form className="loginForm" onSubmit={updateSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                id="name"
                className="form-control filterSelect"
                type="text"
                placeholder="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="Author">
              <label className="custom-label" htmlFor="sonOf">
                Son/Daughter Of :
              </label>
              <input
                id="sonOf"
                className="form-control filterSelect"
                type="text"
                placeholder="son/daughter Of"
                required
                value={sonOf}
                onChange={(e) => setSonOf(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="studentPhoneNumber">
                Student Phone Number :
              </label>
              <input
                id="studentPhoneNumber"
                className="form-control filterSelect"
                type="text"
                placeholder="student Phone Number"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="parentsPhone">
                Parent's Phone :
              </label>
              <input
                id="parentsPhone"
                className="form-control filterSelect"
                type="text"
                placeholder="parent's phone"
                required
                value={parentsPhone}
                onChange={(e) => setParentsPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="address">
                Address :
              </label>
              <input
                id="address"
                className="form-control filterSelect"
                type="text"
                placeholder="address"
                required
                value={address}
                onChange={(e) => setAddress(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="stream">
                Stream :
              </label>
              <input
                id="stream"
                className="form-control filterSelect"
                type="text"
                placeholder="stream"
                required
                value={stream}
                onChange={(e) => setStream(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="rollNumber">
                Roll Number :
              </label>
              <input
                id="rollNumber"
                className="form-control filterSelect"
                type="text"
                placeholder="roll number"
                required
                value={rollNo}
                onChange={(e) => setRollNo(e.target.value)}
              />
            </div>
            <div className="checkb">
              Hostel :
              <label className="checkl">
                <input
                  type="checkbox"
                  checked={hostel}
                  onChange={() => setHostel(!hostel)}
                />
                Yes
              </label>
              <label className="checkl">
                <input
                  type="checkbox"
                  checked={!hostel}
                  onChange={() => setHostel(!hostel)}
                />
                No
              </label>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="adminPassword">
                Admin Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="adminPassword"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>

            <input type="submit" value="UPDATE" className="btn btn-primary vmax1D" />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default UpdateSchoolStudent;
