import React, { Fragment, useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import DataTable from "react-data-table-component";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import "../../../node_modules/bootstrap/dist/css/bootstrap.min.css";
import { Pagination } from "@mui/material";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Books/SearchBook.css";
import {
  clearErrors,
  getAllItems,
  deleteItem,
  addStock,
  removeStock,
} from "../../actions/inventoryActions";
import { toast } from "react-toastify";
import {
  ADD_STOCK_RESET,
  DELETE_ITEM_RESET,
  REMOVE_STOCK_RESET,
} from "../../constants/inventoryConstant";
import InventorySidebar from "../layout/Loader/InventorySidebar";
import Loader from "../layout/Loader/Loader";
import { customStyles } from "../../constant";

const BaseLabComponent = ({ lab }) => {
  const dispatch = useDispatch();

  const { error, items, loading, filterData, totalCount } = useSelector(
    (state) => state.allItems
  );

  const {
    error: deleteError,
    isDeleted,
    isAdded,
    isRemoved,
    loading: updateLoading,
  } = useSelector((state) => state.itemProfile);

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();
  const [id, setId] = useState();
  const [name, setName] = useState();

  const [askedBy, setAskedBy] = useState();
  const [stockd, setStockd] = useState();
  const [costd, setCostd] = useState();

  const [resultsPerPage, setResultsPerPage] = useState(15);
  const [cursor, setCursor] = useState(0);

  const [sortBy, setSortBy] = useState();
  const [sortOrder, setSortOrder] = useState();

  const [costSort, setCostSort] = useState(false);
  const [nameSort, setNameSort] = useState(false);
  const [stockSort, setStockSort] = useState(false);
  const [damagedSort, setDamagedSort] = useState(false);

  const [cursorChange, setCursorChange] = useState(false);
  const [sortChange, setSortChange] = useState(false);
  const [resetFilter, setResetFilter] = useState(false);
  const [resultsPerPageChange, setResultsPerPageChange] = useState(false);
  const [handleFilter, setHandleFilter] = useState(false);

  const [showPassword, setShowPassword] = useState(false);

  const openDialogDel = () => {
    setIsOpen(1);
  };

  const openDialogAdd = () => {
    setIsOpen(2);
  };

  const openDialogRem = () => {
    setIsOpen(3);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(0);
  };

  const makeId = (id) => {
    setId(id);
  };

  const deleteSubmit = () => {
    const temp = password; // kyuki close dialog password ko null krdega toh pehle hi store krna pdega
    closeDialog();
    dispatch(deleteItem(id, temp));
  };

  const addSubmit = () => {
    const temp = password;
    closeDialog();
    const data = {
      cost: costd,
      stock: stockd,
      askedBy,
      password: temp,
    };
    dispatch(addStock(id, data));
  };

  const removeSubmit = () => {
    const temp = password;
    closeDialog();
    const data = {
      stock: stockd,
      askedBy,
      password: temp,
    };
    dispatch(removeStock(id, data));
  };

  const successDelete = () => {
    toast.success("Item Deleted Successfully");
  };
  const successAdd = () => {
    toast.success("Stock added Successfully");
  };
  const successRemove = () => {
    toast.success("Stock Removed Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };

  const handlePageChange = (event) => {
    const page = parseInt(event.target.textContent);
    const offset = (page - 1) * resultsPerPage;
    setCursor(offset);
    setCursorChange(true);
  };

  const handleResultsPerPageChange = (event) => {
    setResultsPerPage(event.target.value);
    setCursor(0);
    setResultsPerPageChange(true);
  };

  const sortFunction = (type) => {
    if (type === "stock") {
      setStockSort(!stockSort);
      setSortBy("stock");
      setSortOrder(stockSort);
    } else if (type === "name") {
      setNameSort(!nameSort);
      setSortBy("name");
      setSortOrder(nameSort);
    } else if (type === "cost") {
      setCostSort(!costSort);
      setSortBy("cost");
      setSortOrder(costSort);
    } else if (type === "damaged") {
      setDamagedSort(!damagedSort);
      setSortBy("damaged");
      setSortOrder(damagedSort);
    }
    setSortChange(true);
  };

  {
    items &&
      items.forEach((item, index) => {
        item.num = cursor + index + 1;
      });
  }

  const columns = [
    {
      selector: (row) => <div className="cellData">{row.num}</div>,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("name")}>
          NAME
        </div>
      ),
      selector: (row) => (
        <div>
          <a className="cellLink" href={`/item/${row._id}`}>
            <p>{row.name}</p>
          </a>
        </div>
      ),
      sortable: true,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("cost")}>
          COST
        </div>
      ),
      selector: (row) => <div className="cellData">{row.cost}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("stock")}>
          STOCK
        </div>
      ),
      selector: (row) => <div className="cellData">{row.stock}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("damaged")}>
          DAMAGED
        </div>
      ),
      selector: (row) => <div className="cellData redClass">{row.damaged}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            makeId(row._id);
            openDialogAdd();
          }}
          className="addBtn"
        >
          ADD
        </button>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            makeId(row._id);
            openDialogRem();
          }}
          className="remBtn"
        >
          REMOVE
        </button>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <a className="rlinks" href={`/update/item/${row._id}`}>
          <button className="butn">EDIT</button>
        </a>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            makeId(row._id);
            openDialogDel();
          }}
          className="delBtn"
        >
          DELETE
        </button>
      ),
    },
  ];

  const filterSubmit = (e) => {
    if (e) e.preventDefault();
    const filterParams = {
      lab,
      name,
      sortBy,
      sortOrder,
      limit: resultsPerPage,
      cursor,
    };
    dispatch(getAllItems(filterParams));
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (deleteError) {
      failure(deleteError);
      dispatch(clearErrors());
    }

    if (isDeleted === true) {
      successDelete();
      dispatch({ type: DELETE_ITEM_RESET });
    }

    if (isAdded) {
      successAdd();
      dispatch({ type: ADD_STOCK_RESET });
    }

    if (isRemoved) {
      successRemove();
      dispatch({ type: REMOVE_STOCK_RESET });
    }

    if (cursorChange) {
      filterSubmit();
      setCursorChange(false);
    } else if (sortChange) {
      filterSubmit();
      setSortChange(false);
    } else if (handleFilter) {
      filterSubmit();
      setHandleFilter(false);
    } else if (resetFilter) {
      filterSubmit();
      setResetFilter(false);
    } else if (resultsPerPageChange) {
      filterSubmit();
      setResultsPerPageChange(false);
    } else if (filterData && filterData.lab === lab) {
      dispatch(
        getAllItems({
          ...filterData,
          limit: filterData.limit ? filterData.limit : 15,
        })
      );
      if (filterData.name) setName(filterData.name);
      if (filterData.sortBy) setSortBy(filterData.sortBy);
      if (filterData.sortOrder) setSortOrder(filterData.sortOrder);
      if (filterData.limit) setResultsPerPage(filterData.limit);
      if (filterData.cursor) setCursor(filterData.cursor);
    } else filterSubmit();
  }, [
    dispatch,
    error,
    deleteError,
    isDeleted,
    isAdded,
    isRemoved,
    cursorChange,
    sortChange,
    resetFilter,
    resultsPerPageChange,
    handleFilter,
  ]);

  return (
    <Fragment>
      {loading || updateLoading ? (
        <Loader />
      ) : (
        <Fragment>
          {isOpen === 1 && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Admin Password"
            >
              <div>
                <form className="loginForm" onSubmit={deleteSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>
                  <button type="submit" className="btn btn-danger vmax1D">
                    DELETE
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          {isOpen === 2 && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Details"
            >
              <div>
                <form className="loginForm" onSubmit={addSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="costd">
                      Cost :
                    </label>
                    <input
                      id="costd"
                      className="form-control filterSelect"
                      type="number"
                      placeholder="cost"
                      value={costd}
                      onChange={(e) => setCostd(e.target.value)}
                    />
                    <label className="custom-label" htmlFor="stockd">
                      Stock :
                    </label>
                    <input
                      id="stockd"
                      className="form-control filterSelect"
                      type="number"
                      placeholder="stock"
                      value={stockd}
                      onChange={(e) => setStockd(e.target.value)}
                    />
                    <label className="custom-label" htmlFor="askedBy">
                      Asked By :
                    </label>
                    <input
                      id="askedBy"
                      className="form-control filterSelect"
                      type="text"
                      placeholder="asked by"
                      value={askedBy}
                      onChange={(e) => setAskedBy(e.target.value)}
                    />
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>
                  <button type="submit" className="btn btn-success vmax1D">
                    ADD
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          {isOpen === 3 && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Admin Password"
            >
              <div>
                <form className="loginForm" onSubmit={removeSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="stockd">
                      Stock :
                    </label>
                    <input
                      id="stockd"
                      className="form-control filterSelect"
                      type="number"
                      placeholder="stock"
                      value={stockd}
                      onChange={(e) => setStockd(e.target.value)}
                    />
                    <label className="custom-label" htmlFor="askedBy">
                      Asked By :
                    </label>
                    <input
                      id="askedBy"
                      className="form-control filterSelect"
                      type="text"
                      placeholder="asked by"
                      value={askedBy}
                      onChange={(e) => setAskedBy(e.target.value)}
                    />
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>

                  <button type="submit" className="btn btn-danger vmax1D">
                    REMOVE
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          <InventorySidebar />
          <div className="dashboard">
            <h4>{lab} items</h4>
            <div className="filters">
              <div className="nameContainer filterDiv">
                <label htmlFor="nameInput">Name</label>
                <input
                  id="nameInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                  }}
                />
              </div>

              <div className="filterButtons">
                <button
                  className="applyButton"
                  onClick={() => {
                    setCursor(0);
                    setHandleFilter(true);
                  }}
                >
                  APPLY
                </button>
                <button
                  className="resetButton"
                  onClick={() => {
                    setName("");
                    setSortBy("");
                    setSortOrder();
                    setCursor(0);
                    setResetFilter(true);
                  }}
                >
                  RESET
                </button>
              </div>
            </div>
            <div className="productListContainer">
              <DataTable
                columns={columns}
                data={items}
                className="productListTable"
                highlightOnHover={true}
                persistTableHead={true}
                fixedHeader={true}
                striped={true}
                dense={true}
                customStyles={customStyles}
              />
              <div className="pagination">
                <div className="resultsPerPageBox">
                  <span>Results Per Page</span>
                  <select
                    className="form-select"
                    value={resultsPerPage}
                    onChange={handleResultsPerPageChange}
                  >
                    {[5, 15, 25, 50, 100].map((results) => (
                      <option key={results} value={results}>
                        {results} Items
                      </option>
                    ))}
                  </select>
                  <span>
                    Showing {cursor + 1} -{" "}
                    {Math.min(totalCount, cursor + resultsPerPage)} of{" "}
                    {totalCount}
                  </span>
                </div>
                <Pagination
                  count={Math.ceil(totalCount / resultsPerPage)}
                  color="primary"
                  onChange={handlePageChange}
                  page={Math.ceil(cursor / resultsPerPage) + 1}
                  siblingCount={2}
                />
              </div>
            </div>
          </div>
        </Fragment>
      )}
      ;
    </Fragment>
  );
};

export default BaseLabComponent;
