import React, { Fragment, useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import DataTable from "react-data-table-component";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import "../../../node_modules/bootstrap/dist/css/bootstrap.min.css";
import { Pagination } from "@mui/material";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Books/SearchBook.css";
import Loader from "../layout/Loader/Loader";
import { toast } from "react-toastify";
import { DELETE_STAFF_RESET } from "../../constants/staffConstant";
import MisSidebar from "../layout/Loader/MisSidebar";
import {
  deleteStaff,
  clearErrors,
  getAllStaff,
} from "../../actions/staffActions";
import { customStyles } from "../../constant";

const SearchStaff = () => {
  const dispatch = useDispatch();

  const { error, staffs, loading, filterData, totalCount } = useSelector(
    (state) => state.allStaff
  );

  const {
    error: deleteError,
    isDeleted,
    loading: deleteLoading,
  } = useSelector((state) => state.staffProfile);

  const [showPassword, setShowPassword] = useState(false);

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();
  const [id, setId] = useState();
  const [designation, setDesignation] = useState();
  const [name, setName] = useState();
  const [subject, setSubject] = useState();

  const [resultsPerPage, setResultsPerPage] = useState(15);
  const [cursor, setCursor] = useState(0);

  const [sortBy, setSortBy] = useState();
  const [sortOrder, setSortOrder] = useState();

  const [salarySort, setSalarySort] = useState(false);
  const [nameSort, setNameSort] = useState(false);
  const [leavesRemSort, setLeavesRemSort] = useState(false);
  const [experienceSort, setExperienceSort] = useState(false);

  const [cursorChange, setCursorChange] = useState(false);
  const [sortChange, setSortChange] = useState(false);
  const [resetFilter, setResetFilter] = useState(false);
  const [resultsPerPageChange, setResultsPerPageChange] = useState(false);
  const [handleFilter, setHandleFilter] = useState(false);

  const salaryLeft = (dateString, salary) => {
    const date1 = new Date(dateString);
    const date2 = new Date(Date.now());

    // Calculate the difference in months
    const monthsDifference =
      (date2.getFullYear() - date1.getFullYear()) * 12 +
      (date2.getMonth() - date1.getMonth()) +
      (date2.getDate() < date1.getDate() && date2.getMonth() > date1.getMonth()
        ? -1
        : 0);

    const dateDiff = date2.getDate() - date1.getDate();
    const days = dateDiff < 0 ? dateDiff + 30 : dateDiff;
    return monthsDifference * salary + days * (salary / 30);
  };

  {
    staffs &&
      staffs.forEach((staff) => {
        staff.salaryRem = staff.lastMonthPaid
          ? salaryLeft(staff.lastMonthPaid, staff.salary)
          : 0;
        staff.salaryRem -=
          staff.deductionLeaves * Math.round(staff.salary / 30);
        staff.salaryRem = Math.ceil(staff.salaryRem);
      });
  }

  const openDialog = () => {
    setIsOpen(true);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(false);
  };

  const makeId = (id) => {
    setId(id);
  };

  const deleteSubmit = () => {
    const temp = password;
    closeDialog();
    dispatch(deleteStaff(id, temp));
  };

  const successDelete = () => {
    toast.success("Staff Deleted Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };

  const handlePageChange = (event) => {
    const page = parseInt(event.target.textContent);
    const offset = (page - 1) * resultsPerPage;
    setCursor(offset);
    setCursorChange(true);
  };

  const handleResultsPerPageChange = (event) => {
    setResultsPerPage(event.target.value);
    setCursor(0);
    setResultsPerPageChange(true);
  };

  const sortFunction = (type) => {
    if (type === "salary") {
      setSalarySort(!salarySort);
      setSortBy("salary");
      setSortOrder(salarySort);
    } else if (type === "name") {
      setNameSort(!nameSort);
      setSortBy("name");
      setSortOrder(nameSort);
    } else if (type === "leavesRem") {
      setLeavesRemSort(!leavesRemSort);
      setSortBy("leavesRem");
      setSortOrder(leavesRemSort);
    } else if (type === "experience") {
      setExperienceSort(!experienceSort);
      setSortBy("experience");
      setSortOrder(experienceSort);
    }
    setSortChange(true);
  };

  {
    staffs &&
      staffs.forEach((staff, index) => {
        staff.num = cursor + index + 1;
      });
  }

  const columns = [
    {
      selector: (row) => <span className="cellData">{row.num}</span>,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("name")}>
          NAME
        </div>
      ),
      selector: (row) => (
        <div>
          <a className="cellLink" href={`/staff/${row._id}`}>
            <p>{row.name.toUpperCase()}</p>
          </a>
        </div>
      ),
      sortable: true,
      wrap: true,
    },
    {
      name: <div className="headings">PHONE</div>,
      selector: (row) => <spdiv className="cellData">{row.phone}</spdiv>,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("salary")}>
          SALARY
        </div>
      ),
      selector: (row) => <div className="cellData">{row.salary}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("salaryRem")}>
          SALARY REMAINING
        </div>
      ),
      selector: (row) => <div className="cellData">{row.salaryRem}</div>,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("leavesRem")}>
          LEAVES REMAINING
        </div>
      ),
      selector: (row) => (
        <div className="cellData">{row.leavesAllowed - row.leavesUsed}</div>
      ),
      wrap: true,
      sortable: true,
    },
    {
      name: <div className="headings">QUALIFICATION</div>,
      selector: (row) => (
        <div className="cellData">
          {row.qualification && row.qualification.toUpperCase()}
        </div>
      ),
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("experience")}>
          EXPERIENCE
        </div>
      ),
      selector: (row) => <div className="cellData">{row.experience}</div>,
      wrap: true,
      sortable: true,
    },
    {
      name: <div className="headings">DESIGNATION</div>,
      selector: (row) => (
        <div className="cellData">
          {row.designation && row.designation.toUpperCase()}
        </div>
      ),
      wrap: true,
    },
    {
      name: <div className="headings">SALARY CLEARED TILL</div>,
      selector: (row) => <div className="cellData">{row.lastMonthPaid}</div>,
      wrap: true,
    },
    {
      name: <div className="headings">SUBJECT</div>,
      selector: (row) => (
        <div className="cellData">
          {row.subject && row.subject.toUpperCase()}
        </div>
      ),
      wrap: true,
    },
    {
      name: "",
      cell: (row) => (
        <a className="rlinks" href={`/update/staff/${row._id}`}>
          <button className="butn">EDIT</button>
        </a>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            openDialog();
            makeId(row._id);
          }}
          className="delBtn"
        >
          DELETE
        </button>
      ),
    },
  ];

  const filterSubmit = (e) => {
    if (e) e.preventDefault();
    const filterParams = {
      name,
      designation,
      subject,
      sortBy,
      sortOrder,
      limit: resultsPerPage,
      cursor,
    };
    dispatch(getAllStaff(filterParams));
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (deleteError) {
      failure(deleteError);
      dispatch(clearErrors());
    }

    if (isDeleted === true) {
      successDelete();
      dispatch({ type: DELETE_STAFF_RESET });
    }

    if (cursorChange) {
      filterSubmit();
      setCursorChange(false);
    } else if (sortChange) {
      filterSubmit();
      setSortChange(false);
    } else if (resetFilter) {
      filterSubmit();
      setResetFilter(false);
    } else if (resultsPerPageChange) {
      filterSubmit();
      setResultsPerPageChange(false);
    } else if (handleFilter) {
      filterSubmit();
      setHandleFilter(false);
    } else if (filterData) {
      dispatch(
        getAllStaff({
          ...filterData,
          limit: filterData.limit ? filterData.limit : 15,
        })
      );
      if (filterData.name) setName(filterData.name);
      if (filterData.designation) setDesignation(filterData.designation);
      if (filterData.subject) setSubject(filterData.subject);
      if (filterData.sortBy) setSortBy(filterData.sortBy);
      if (filterData.sortOrder) setSortOrder(filterData.sortOrder);
      if (filterData.limit) setResultsPerPage(filterData.limit);
      if (filterData.cursor) setCursor(filterData.cursor);
    } else filterSubmit();
  }, [
    dispatch,
    error,
    deleteError,
    isDeleted,
    cursorChange,
    sortChange,
    resetFilter,
    resultsPerPageChange,
    handleFilter,
  ]);

  return (
    <Fragment>
      {loading || deleteLoading ? (
        <Loader />
      ) : (
        <Fragment>
          {isOpen && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Admin Password"
            >
              <div>
                <form className="loginForm" onSubmit={deleteSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>
                  <button type="submit" className="btn btn-danger vmax1D">
                    DELETE
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          <MisSidebar />
          <div className="dashboard">
            <div className="filters">
              <div className="nameContainer filterDiv">
                <label htmlFor="nameInput">Name</label>
                <input
                  id="nameInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                  }}
                />
              </div>

              <div className="rollNoContainer filterDiv">
                <label htmlFor="rollNoInput">Subject</label>
                <input
                  id="rollNoInput"
                  type="text"
                  className="form-control rollNoSelect name"
                  placeholder="Subject"
                  value={subject}
                  onChange={(e) => {
                    setSubject(e.target.value);
                  }}
                />
              </div>

              <div className="rollNoContainer filterDiv">
                <label htmlFor="rollNoInput">Designation</label>
                <input
                  id="rollNoInput"
                  type="text"
                  className="form-control rollNoSelect name"
                  placeholder="Designation"
                  value={designation}
                  onChange={(e) => {
                    setDesignation(e.target.value);
                  }}
                />
              </div>

              <div className="filterButtons">
                <button
                  className="applyButton"
                  onClick={() => {
                    setCursor(0);
                    setHandleFilter(true);
                  }}
                >
                  APPLY
                </button>
                <button
                  className="resetButton"
                  onClick={() => {
                    setDesignation("");
                    setName("");
                    setSubject("");
                    setSortBy("");
                    setSortOrder();
                    setCursor(0);
                    setResetFilter(true);
                  }}
                >
                  RESET
                </button>
              </div>
            </div>
            <div className="productListContainer">
              <DataTable
                columns={columns}
                data={staffs}
                className="productListTable"
                highlightOnHover={true}
                persistTableHead={true}
                fixedHeader={true}
                striped={true}
                dense={true}
                customStyles={customStyles}
              />
              <div className="pagination">
                <div className="resultsPerPageBox">
                  <span>Results Per Page</span>
                  <select
                    className="form-select"
                    value={resultsPerPage}
                    onChange={handleResultsPerPageChange}
                  >
                    {[5, 15, 25, 50, 100].map((results) => (
                      <option key={results} value={results}>
                        {results} Staff
                      </option>
                    ))}
                  </select>
                  <span>
                    Showing {cursor + 1} -{" "}
                    {Math.min(totalCount, cursor + resultsPerPage)} of{" "}
                    {totalCount}
                  </span>
                </div>
                <Pagination
                  count={Math.ceil(totalCount / resultsPerPage)}
                  color="primary"
                  onChange={handlePageChange}
                  page={Math.ceil(cursor / resultsPerPage) + 1}
                  siblingCount={2}
                />
              </div>
            </div>
          </div>
        </Fragment>
      )}
    </Fragment>
  );
};

export default SearchStaff;
