import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { UPDATE_STAFF_RESET } from "../../constants/staffConstant";
import MisSidebar from "../layout/Loader/MisSidebar";
import {
  getStaffDetails,
  updateStaff,
  clearErrors,
} from "../../actions/staffActions";

const UpdateStaff = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { id } = useParams();

  const { loading, isUpdated, error } = useSelector(
    (state) => state.staffProfile
  );
  const {
    loading: staffLoading,
    error: staffError,
    staff,
  } = useSelector((state) => state.staffDetails);

  const [showPassword, setShowPassword] = useState(false);

  const [name, setName] = useState();
  const [phone, setPhone] = useState();
  const [qualification, setQualification] = useState();
  const [salary, setSalary] = useState();
  const [salaryClearedTill, setSalaryClearedTill] = useState();
  const [leavesAllowed, setLeavesAllowed] = useState();
  const [experience, setExperience] = useState();
  const [designation, setDesignation] = useState();
  const [subject, setSubject] = useState();
  const [password, setPassword] = useState();
  const [photo, setPhoto] = useState(null);
  const [pgCertificate, setPgCertificate] = useState(null);
  const [appointment, setAppointment] = useState(null);
  const [aadhar, setAadhar] = useState(null);

  const updateSubmit = (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("phone", phone);
      formData.append("qualification", qualification);
      formData.append("salaryClearedTill", salaryClearedTill);
      formData.append("salary", salary);
      formData.append("leavesAllowed", leavesAllowed);
      formData.append("experience", experience);
      formData.append("designation", designation);
      formData.append("subject", subject);
      formData.append("password", password);
      if (photo) {
        formData.append("photo", photo);
      }
      if (pgCertificate) {
        formData.append("pgCertificate", pgCertificate);
      }
      if (aadhar) {
        formData.append("aadhar", aadhar);
      }
      if (appointment) {
        formData.append("appointment", appointment);
      }
      dispatch(updateStaff(id, formData));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Staff Updated Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (!staff || (staff && staff._id !== id)) dispatch(getStaffDetails(id));
    else {
      setName(staff.name);
      setPhone(staff.phone);
      setSalary(staff.salary);
      setQualification(staff.qualification);
      setLeavesAllowed(staff.leavesAllowed);
      setDesignation(staff.designation);
      setSubject(staff.subject);
      setSalaryClearedTill(staff.lastMonthPaid);
      setExperience(staff.experience);
    }
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }
    if (staffError) {
      failure(staffError);
      dispatch(clearErrors());
    }
    if (isUpdated) {
      //  alert.success("Profile updated successfully");
      success();
      navigate(`/staff/${staff._id}`);
      dispatch({ type: UPDATE_STAFF_RESET });
    }
  }, [dispatch, error, isUpdated, id, staff]);

  return (
    <Fragment>
      {loading || staffLoading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <MisSidebar />
          <h4>Update Staff</h4>
          <form className="loginForm" onSubmit={updateSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                id="name"
                className="form-control filterSelect"
                type="text"
                placeholder="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="staffPhoneNumber">
                Staff Phone Number :
              </label>
              <input
                id="staffPhoneNumber"
                className="form-control filterSelect"
                type="text"
                placeholder="staff Phone Number"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="qualification">
                Maximum Qualification :
              </label>
              <input
                id="qualification"
                className="form-control filterSelect"
                type="text"
                placeholder="maximum qualification"
                required
                value={qualification}
                onChange={(e) => setQualification(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="salary">
                Salary :
              </label>
              <input
                id="salary"
                className="form-control filterSelect"
                type="number"
                placeholder="salary"
                required
                value={salary}
                onChange={(e) => setSalary(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="leavesAllowed">
                Leaves Allowed :
              </label>
              <input
                id="leavesAllowed"
                className="form-control filterSelect"
                type="number"
                placeholder="leavesAllowed"
                required
                value={leavesAllowed}
                onChange={(e) => setLeavesAllowed(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="experience">
                Experience in Years :
              </label>
              <input
                id="experience"
                className="form-control filterSelect"
                type="number"
                placeholder="experience in years"
                required
                value={experience}
                onChange={(e) => setExperience(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="designation">
                Designation :
              </label>
              <input
                id="designation"
                className="form-control filterSelect"
                type="text"
                placeholder="designation"
                required
                value={designation}
                onChange={(e) => setDesignation(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="subject">
                Subject :
              </label>
              <input
                id="subject"
                className="form-control filterSelect"
                type="text"
                placeholder="subject"
                required
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="checks" htmlFor="salaryClearedTill">
                Salary Cleared till Date :
              </label>
              <input
                id="salaryClearedTill"
                className="form-control filterSelect"
                type="date"
                placeholder="salary cleared till"
                required
                value={salaryClearedTill}
                onChange={(e) => setSalaryClearedTill(e.target.value)}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="photo">
                Photo :
              </label>
              <input
                id="photo"
                className="form-control filterSelect"
                type="file"
                accept="application/pdf"
                onChange={(e) => setPhoto(e.target.files[0])}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="pgCertificate">
                Highest Degree Certificate :
              </label>
              <input
                id="pgCertificate"
                className="form-control filterSelect"
                type="file"
                accept="application/pdf"
                onChange={(e) => setPgCertificate(e.target.files[0])}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="aadhar">
                Aadhar :
              </label>
              <input
                id="aadhar"
                className="form-control filterSelect"
                type="file"
                accept="application/pdf"
                onChange={(e) => setAadhar(e.target.files[0])}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="appointment">
                Appointment :
              </label>
              <input
                id="appointment"
                className="form-control filterSelect"
                type="file"
                accept="application/pdf"
                onChange={(e) => setAppointment(e.target.files[0])}
              />
            </div>

            <div className="password">
              <label className="custom-label" htmlFor="adminPassword">
                Admin Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="adminPassword"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>

            <input
              type="submit"
              value="UPDATE"
              className="btn btn-primary vmax1D"
            />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default UpdateStaff;
