import React,{useEffect,useState,Fragment} from "react";
import { useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import {toast} from "react-toastify"; 
import  {ReactDialogBox}  from "react-js-dialog-box";
import "./Homepage.css";
import { Link } from "react-router-dom";
import { RiErrorWarningFill } from "react-icons/ri";

import logo from "../../images/collegeLogo.png";
import "./LibraryHome.css"
import { clearErrors, getCurrentYear, resetLeaves } from "../../actions/staffActions";
import { RESET_LEAVES_RESET } from "../../constants/staffConstant";
import Loader from "../layout/Loader/Loader";


function Homepage() {

  const dispatch = useDispatch();
  const {currentYear,loading,error} = useSelector(state => state.currentYearDetails);
  const {isReset, loading: resetLoading,error:resetError} = useSelector(state => state.staffProfile);

  const dateT = new Date(Date.now());
  const month = dateT.getMonth();
  const year = dateT.getFullYear();

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();

  const openDialog = () => {
    setIsOpen(true);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(false);
  };

  const resetSubmit = (e) => {
    e.preventDefault();
    const temp = password;
    closeDialog();
    try {
      dispatch(resetLeaves(temp));
    } catch (err) {
      toast.error(err);
    }
  };

  const success = () => {
    toast.success("Leaves reset Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };


  useEffect(()=>{
    if(error){
        failure(error);
        dispatch(clearErrors());     
    }
    else if(resetError){
        failure(resetError);
        dispatch(clearErrors());
    }
    if(isReset){
       success();
       dispatch({type:RESET_LEAVES_RESET});
    }
   dispatch(getCurrentYear());
  },[dispatch,isReset,currentYear])
  
  return (loading || resetLoading) ? <Loader/> :  (
    <>
    {isOpen && (
        <ReactDialogBox
          closeBox={closeDialog}
          modalWidth="28%"
          headerBackgroundColor="rgb(192, 188, 188)"
          headerTextColor="rgb(39, 39, 39)"
          headerHeight="50"
          closeButtonColor="#D92736"
          bodyBackgroundColor="white"
          bodyTextColor="black"
          bodyHeight="35%"
          headerText="Enter Admin Password"
        >
          <div>
            <form className="loginForm" onSubmit={resetSubmit}>
              <div className="password">
                <input
                  type="password"
                  placeholder="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                ></input>
              </div>
              <button type="submit" className="loginBtn">
                Reset
              </button>
            </form>
          </div>
        </ReactDialogBox>
      )}
    <div className="container">
    <div className="libContainer">
      <p className="heading">Modern College Management Site</p>
      {(month >= 3 && (currentYear && year > currentYear)) && 
      <button 
         className="resetL"
         onClick={() => {
            openDialog();
         }}
      >
         <RiErrorWarningFill /> 
          <span>Reset Leaves</span>
      </button> }
      <img src = {logo} />
      <div>
        <p>Instructions</p>
        <div>
          <p className = "inst"><span className="instSpan">1. </span>Try that every field where text is to be filled should have capital letters (except passwords)</p>
          <p className = "inst"><span className="instSpan">2. </span>Correct spellings must be entered</p>
          <p className = "inst"><span className="instSpan">3. </span>Before entering any student into a degree/stream the fee structure for that degree/stream must be present</p>
        </div>
      </div>
    </div>
    </div>
    </>
  );
}

export default Homepage;
