import {
    ALL_STAFF_FAIL,
    ALL_STAFF_REQUEST,
    ALL_STAFF_SUCCESS,
    STAFF_DETAILS_FAIL,
    STAFF_DETAILS_REQUEST,
    STAFF_DETAILS_SUCCESS,
    CLEAR_ERRORS,
    CREATE_STAFF_FAIL,
    CREATE_STAFF_REQUEST,
    CREATE_STAFF_RESET,
    CREATE_STAFF_SUCCESS,
    UPDATE_STAFF_FAIL,
    UPDATE_STAFF_REQUEST,
    UPDATE_STAFF_RESET,
    UPDATE_STAFF_SUCCESS,
    DELETE_STAFF_FAIL,
    DELETE_STAFF_REQUEST,
    DELETE_STAFF_RESET,
    DELETE_STAFF_SUCCESS,
    CURRENT_YEAR_FAIL,
    CURRENT_YEAR_REQUEST,
    CURRENT_YEAR_SUCCESS,
    RESET_LEAVES_FAIL,
    RESET_LEAVES_REQUEST,
    RESET_LEAVES_SUCCESS
} from "../constants/staffConstant"

import axios from "axios"
import { CREATE_USER_FAIL } from "../constants/usersConstant";

export const createStaff = (userData) => async(dispatch) => {
    try{
        dispatch({type:CREATE_STAFF_REQUEST});
        const config = { headers: { "Content-Type": "multipart/form-data" } };
        const {data} = await axios.post(`/api/v1/staff/create`,userData,config);
        dispatch({
            type:CREATE_STAFF_SUCCESS,
            payload:data
        })
    } 
    catch(error){
        dispatch({
            type:CREATE_USER_FAIL,
            payload:error.response.data.message,
        })
    }
};

export const getAllStaff = (filterData) => async(dispatch) => {
    try{
          dispatch({
            type:ALL_STAFF_REQUEST,
            payload:filterData
          });
          let url = "/api/v1/staffs";
          if (filterData) {
            const filteredData = Object.fromEntries(
              Object.entries(filterData).filter(([_, value]) => (value !== undefined && value !== ""))
            );
      
            const queryParams = new URLSearchParams(filteredData).toString();
            if (queryParams) {
              url += `?${queryParams}`;
            }
          }
          const {data} = await axios.get(url);
          console.log(data,url);
          dispatch({
            type:ALL_STAFF_SUCCESS,
            payload:data
          })
    }
    catch(error){
        dispatch({
            type:ALL_STAFF_FAIL,
            payload:error
        })
    }
}

// get staff details
export const getStaffDetails = (id) => async(dispatch) =>{
    try{
         dispatch({
            type:STAFF_DETAILS_REQUEST
         })
        const {data} = await axios.get(`/api/v1/staff/${id}`);
        dispatch({
            type:STAFF_DETAILS_SUCCESS,
            payload:data.staff
        })
    }
    catch(error){
        dispatch({
            type:STAFF_DETAILS_FAIL,
            payload:error.response.data.message
        })
    }
}

// Update User
export const updateStaff = (id, userData) => async (dispatch) => {
    try {
      dispatch({ type: UPDATE_STAFF_REQUEST });
  
      const config = { headers: { "Content-Type": "multipart/form-data" } };
  
      const { data } = await axios.put(`/api/v1/staff/${id}`, userData, config);
  
      dispatch({ type: UPDATE_STAFF_SUCCESS, payload: data.success });
    } catch (error) {
      dispatch({
        type: UPDATE_STAFF_FAIL,
        payload: error.response.data.message,
      });
    }
  };

  
  // Delete User
  export const deleteStaff = (id, password) => async (dispatch) => {
    try {
      dispatch({ type: DELETE_STAFF_REQUEST });
  
      const { data } = await axios.post(`/api/v1/staff/${id}`, { password });
  
      dispatch({ type: DELETE_STAFF_SUCCESS, payload: data });
    } catch (error) {
      dispatch({
        type: DELETE_STAFF_FAIL,
        payload: error.response.data.message,
      });
    }
  };
  
  // get current year
  export const getCurrentYear = () => async (dispatch) => {
    try {
      dispatch({ type: CURRENT_YEAR_REQUEST });
  
      const { data } = await axios.get(`/api/v1/staff/currentYear`);
  
      dispatch({ type: CURRENT_YEAR_SUCCESS, payload: data.currentYear });
    } catch (error) {
      dispatch({
        type: CURRENT_YEAR_FAIL,
        payload: error.response.data.message,
      });
    }
  };

  // Reset Leaves
export const resetLeaves = (password) => async (dispatch) => {
  try {
    dispatch({ type: RESET_LEAVES_REQUEST});

    const config = { headers: { "Content-Type": "application/json" } };

    const { data } = await axios.put(`/api/v1/staff/refresh`, {password}, config);

    dispatch({ type: RESET_LEAVES_SUCCESS, payload: data});
  } catch (error) {
    dispatch({
      type: RESET_LEAVES_FAIL,
      payload: error.response.data.message,
    });
  }
};

  // to clear errors
  export const clearErrors = () => async (dispatch) => {
    dispatch({
      type: CLEAR_ERRORS,
    });
  };