import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  login,
  clearErrors,
  updatePhone,
  loadAdmin,
  updatePassword,
} from "../../actions/adminActions";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "./UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import adminImage from "../../images/adminImage.png";
import { UPDATE_PASSWORD_RESET } from "../../constants/adminConstant";

const UpdatePassword = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [oldPassword, setOldPassword] = useState();
  const [newPassword, setNewPassword] = useState();
  const [confirmPassword, setConfirmPassword] = useState();
  const [showPassword, setShowPassword] = useState(false);

  const { loading, isUpdated, error } = useSelector(
    (state) => state.adminProfile
  );

  const updateSubmit = (e) => {
    e.preventDefault();
    const data = {
      oldPassword,
      newPassword,
      confirmPassword,
    };
    dispatch(updatePassword(data));
  };

  const success = () => {
    toast.success("Admin Password Updated Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isUpdated) {
      //  alert.success("Profile updated successfully");
      success();
      navigate("/");
      dispatch({ type: UPDATE_PASSWORD_RESET });
    }
  }, [dispatch, error, isUpdated]);
  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <h4>Update Password</h4>
          <img src={adminImage} />
          <form className="loginForm" onSubmit={updateSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="currentPassword">
                Current Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Current Password"
                  className="form-control filterSelect"
                  id="currentPassword"
                  required
                  value={oldPassword}
                  onChange={(e) => setOldPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <div className="name">
              <label className="custom-label" htmlFor="newPassword">
                New Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="New Password"
                  className="form-control filterSelect"
                  id="newPassword"
                  required
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="confirmPassword">
                Confirm New Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Confirm Password"
                  className="form-control filterSelect"
                  id="confirmPassword"
                  required
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input
              type="submit"
              value="UPDATE"
              className="btn btn-primary vmax1D"
            />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default UpdatePassword;
