import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  clearErrors,
  withdrawBook
} from "../../actions/booksActions";
import { useNavigate} from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import { WITHDRAW_BOOK_RESET } from "../../constants/booksConstant";
import LibrarySidebar from "../layout/Loader/LibrarySidebar";

const WithdrawBook = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { loading, isWithdrawn, error } = useSelector(
    (state) => state.bookProfile
  );


  const [bookNumber, setBookNumber] = useState();
  const [borrowerName, setBorrowerName] = useState();
  const [borrowerPhone,setBorrowerPhone] = useState();
  const [password, setPassword] = useState();
  const [showPassword, setShowPassword] = useState(false);

  const withdrawSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        number:bookNumber,
        borrowerName:borrowerName.toLowerCase(),
        borrowerPhone,
        password
      };
      dispatch(withdrawBook(data));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Book Withdraw Successful");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isWithdrawn) {
      //  alert.success("Profile updated successfully");
      success();
      navigate("/library");
      dispatch({ type: WITHDRAW_BOOK_RESET});
    }
  }, [dispatch, error, isWithdrawn]);

  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <LibrarySidebar/>
          <h4>Withdraw Book</h4>
          <form className="loginForm" onSubmit={withdrawSubmit} autocomplete="off">
            <div className="loginPhone">
              <label htmlFor="bookNumber" className="custom-label">Book Number :</label>
              <input
                type="text"
                placeholder="Book Number"
                id="bookNumber"
                className="form-control filterSelect"
                required
                value={bookNumber}
                onChange={(e) => setBookNumber(e.target.value)}
              />
            </div>
            <div className="name">
              <label htmlFor="borrowerName" className="custom-label">Borrower Name :</label>
              <input
                type="text"
                placeholder="Borrower Name"
                id="borrowerName"
                className="form-control filterSelect"
                required
                value={borrowerName}
                onChange={(e) => setBorrowerName(e.target.value)}
              />
            </div>
            <div className="name">
              <label htmlFor="borrowerPhone" className="custom-label">Borrower Phone :</label>
              <input
                type="text"
                id="borrowerPhone"
                placeholder="Borrower Phone Number"
                className="form-control filterSelect"
                required
                value={borrowerPhone}
                onChange={(e) => setBorrowerPhone(e.target.value)}
              />
            </div>
            <div className="password">
              <label htmlFor="password" className="custom-label">Password :</label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input type="submit" value="WITHDRAW" className="btn btn-primary vmax1D" />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default WithdrawBook;
