import {
    CREATE_SSTUDENT_FAIL,
    CREATE_SSTUDENT_REQUEST,
    CLEAR_ERRORS,
    CREATE_SSTUDENT_RESET,
    CREATE_SSTUDENT_SUCCESS,
    ALL_SSTUDENTS_FAIL,
    ALL_SSTUDENTS_REQUEST,
    ALL_SSTUDENTS_SUCCESS,
    SSTUDENT_DETAILS_FAIL,
    SSTUDENT_DETAILS_REQUEST,
    SSTUDENT_DETAILS_SUCCESS,
    DELETE_SSTUDENT_FAIL,
    DELETE_SSTUDENT_REQUEST,
    DELETE_SSTUDENT_RESET,
    DELETE_SSTUDENT_SUCCESS,
    UPDATE_SSTUDENT_FAIL,
    UPDATE_SSTUDENT_REQUEST,
    UPDATE_SSTUDENT_RESET,
    UPDATE_SSTUDENT_SUCCESS,
    PAYMENT_SSTUDENT_FAIL,
    PAYMENT_SSTUDENT_REQUEST,
    PAYMENT_SSTUDENT_RESET,
    PAYMENT_SSTUDENT_SUCCESS,
    UPDATE_GRADE_FAIL,
    UPDATE_GRADE_REQUEST,
    UPDATE_GRADE_RESET,
    UPDATE_GRADE_SUCCESS,
    CREATE_SSTUDENT_EXCEL_FAIL,
    CREATE_SSTUDENT_EXCEL_REQUEST,
    CREATE_SSTUDENT_EXCEL_SUCCESS,
    STUDENT_PASSED_FAIL,
    STUDENT_PASSED_REQUEST,
    STUDENT_PASSED_RESET,
    STUDENT_PASSED_SUCCESS
} from "../constants/schoolStudentConstant";
import axios from "axios";

//create student
export const createSchoolStudent = (schoolStudentData) => async (dispatch) => {
    try {
      dispatch({ type: CREATE_SSTUDENT_REQUEST });
  
      const config = { headers: { "Content-Type": "application/json" } };
      const { data } = await axios.post(
        `/api/v1/schoolStudent/create`,
        schoolStudentData,
        config
      );
      dispatch({ type: CREATE_SSTUDENT_SUCCESS, payload: data });
    } catch (error) {
      dispatch({
        type: CREATE_SSTUDENT_FAIL,
        payload: error.response.data.message,
      });
    }
  };


  export const createScoolStudentFromExcelFile =
  (formData) => async (dispatch) => {
    try {
      dispatch({ type: CREATE_SSTUDENT_EXCEL_REQUEST });

      const config = { headers: { "Content-Type": "multipart/form-data" } };
      const { data } = await axios.post(
        `/api/v1/schoolStudent/create/file`,
        formData,
        config
      );
      dispatch({ type: CREATE_SSTUDENT_EXCEL_SUCCESS, payload: data });
    } catch (error) {
      dispatch({
        type: CREATE_SSTUDENT_EXCEL_FAIL,
        payload: error.response.data.message,
      });
    }
  };
  
  // get All Students
  export const getAllSchoolStudents =
  (filterData) =>
    async (dispatch) => {
      try {
        dispatch({ type: ALL_SSTUDENTS_REQUEST, payload:filterData });
        if (filterData && filterData.batch) {
          if (!filterData.rollNo || filterData.rollNo.endsWith('-'))
            filterData.rollNo =
              filterData.batch.length >= 2
                ? filterData.batch.slice(-2) + "-"
                : filterData.batch;
          delete filterData.batch;
        }
        let url = "/api/v1/schoolStudents";
        if (filterData) {
          const filteredData = Object.fromEntries(
            Object.entries(filterData).filter(([_, value]) => (value !== undefined && value !== ""))
          );
    
          const queryParams = new URLSearchParams(filteredData).toString();
          if (queryParams) {
            url += `?${queryParams}`;
          }
        }
        const { data } = await axios.get(url);
  
        dispatch({ type: ALL_SSTUDENTS_SUCCESS, payload: data });
      } catch (error) {
        dispatch({ type: ALL_SSTUDENTS_FAIL, payload: error });
      }
    };
  
  // get  Student Details
  export const getSchoolStudentDetails = (id) => async (dispatch) => {
    try {
      dispatch({ type: SSTUDENT_DETAILS_REQUEST });
      const { data } = await axios.get(`/api/v1/schoolStudent/${id}`);
  
      dispatch({ type: SSTUDENT_DETAILS_SUCCESS, payload: data.schoolStudent });
    } catch (error) {
      dispatch({ type: SSTUDENT_DETAILS_FAIL, payload: error.response.data.message });
    }
  };
  
