import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { login, clearErrors } from "../../actions/adminActions";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "./Login.css";
import Loader from "../layout/Loader/Loader";
import collegeLogo from "../../images/collegeLogo.png";

const Login = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  const { loading, error, isAuthenticated } = useSelector(
    (state) => state.admin
  );

  const success = () => {
    toast.success("Login Successful");
  };
  const failure = (error) => {
    toast.error(error);
  };

  const loginSubmit = (e) => {
    e.preventDefault();
    try {
      dispatch(login(phone, password));
    } catch (err) {}
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isAuthenticated) {
      success();
      navigate("/");
    }
  }, [dispatch, error, isAuthenticated]);
  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="card">
          <img src={collegeLogo} />
          <p className="college">Modern College Dharmagarh Maintainence Site</p>
          <p>Login With Registered Phone Number and Password to Access</p>
          <form className="loginForm" onSubmit={loginSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="phone">
                Phone :
              </label>
              <input
                type="text"
                placeholder="phone"
                className="form-control filterSelect"
                id="phone"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
            </div>
            <div className="loginPassword">
              <label className="custom-label" htmlFor="password">
                Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Password"
                  className="form-control filterSelect"
                  id="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input
              type="submit"
              value="LOGIN"
              className="btn btn-primary vmax1D"
            />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default Login;
