import React, { Fragment, useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import DataTable from "react-data-table-component";
import { ReactDialogBox } from "react-js-dialog-box";
import "react-js-dialog-box/dist/index.css";
import "../../../node_modules/bootstrap/dist/css/bootstrap.min.css";
import { Pagination } from "@mui/material";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Books/SearchBook.css";
import {
  clearErrors,
  getAllCollegeStudents,
  deleteCollegeStudent,
} from "../../actions/collegeStudentActions";
import { toast } from "react-toastify";
import { DELETE_CSTUDENT_RESET } from "../../constants/collegeStudentConstant";
import FeeSidebar from "../layout/Loader/FeeSidebar";
import {
  batches,
  degrees,
  collegeStreams as streams,
  customStyles,
} from "../../constant";
import Loader from "../layout/Loader/Loader";

const SearchCollegeStudent = () => {
  const dispatch = useDispatch();

  const { error, collegeStudents, filterData, loading, totalCount } =
    useSelector((state) => state.allCollegeStudents);

  const {
    error: deleteError,
    isDeleted,
    loading: deleteLoading,
  } = useSelector((state) => state.collegeStudentProfile);

  const [showPassword, setShowPassword] = useState(false);

  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState();
  const [id, setId] = useState();
  const [batch, setBatch] = useState();
  const [name, setName] = useState();
  const [degree, setDegree] = useState();
  const [rollNo, setRollNo] = useState();
  const [stream, setStream] = useState();
  const [hostel, setHostel] = useState();
  const [semester, setSemester] = useState();

  const [resultsPerPage, setResultsPerPage] = useState(15);
  const [cursor, setCursor] = useState(0);

  const [sortBy, setSortBy] = useState();
  const [sortOrder, setSortOrder] = useState();

  const [rollNoSort, setRollNoSort] = useState(false);
  const [nameSort, setNameSort] = useState(false);
  const [semesterSort, setSemesterSort] = useState(false);
  const [feeDueSort, setFeeDueSort] = useState(false);

  const [cursorChange, setCursorChange] = useState(false);
  const [sortChange, setSortChange] = useState(false);
  const [resetFilter, setResetFilter] = useState(false);
  const [resultsPerPageChange, setResultsPerPageChange] = useState(false);
  const [handleFilter, setHandleFilter] = useState(false);

  const openDialog = () => {
    setIsOpen(true);
  };

  const closeDialog = () => {
    setPassword();
    setIsOpen(false);
  };

  const makeId = (id) => {
    setId(id);
  };

  const deleteSubmit = () => {
    const temp = password;
    closeDialog();
    dispatch(deleteCollegeStudent(id, temp));
  };

  const successDelete = () => {
    toast.success("Student Deleted Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };

  const handlePageChange = (event) => {
    const page = parseInt(event.target.textContent);
    const offset = (page - 1) * resultsPerPage;
    setCursor(offset);
    setCursorChange(true);
  };

  const handleResultsPerPageChange = (event) => {
    setResultsPerPage(event.target.value);
    setCursor(0);
    setResultsPerPageChange(true);
  };

  const sortFunction = (type) => {
    if (type === "rollNo") {
      setRollNoSort(!rollNoSort);
      setSortBy("rollNo");
      setSortOrder(rollNoSort);
    } else if (type === "name") {
      setNameSort(!nameSort);
      setSortBy("name");
      setSortOrder(nameSort);
    } else if (type === "feeDue") {
      setFeeDueSort(!feeDueSort);
      setSortBy("feeLeft");
      setSortOrder(feeDueSort);
    } else if (type === "semester") {
      setSemesterSort(!semesterSort);
      setSortBy("semester");
      setSortOrder(semesterSort);
    }
    setSortChange(true);
  };

  {
    collegeStudents &&
      collegeStudents.forEach((collegeStudent, index) => {
        collegeStudent.num = cursor + index + 1;
      });
  }

  const columns = [
    {
      selector: (row) => <div className="cellData">{row.num}</div>,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("rollNo")}>
          ROLL NO
        </div>
      ),
      selector: (row) => <div className="cellData">{row.rollNo}</div>,
      sortable: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("name")}>
          NAME
        </div>
      ),
      selector: (row) => (
        <div>
          <a className="cellLink" href={`/collegeStudent/${row._id}`}>
            <p>{row.name}</p>
          </a>
        </div>
      ),
      sortable: true,
      wrap: true,
    },
    {
      name: <div className="headings">DEGREE</div>,
      selector: (row) => <div className="cellData">{row.degree}</div>,
      wrap: true,
    },
    {
      name: <div className="headings">PHONE</div>,
      selector: (row) => <div className="cellData">{row.phone}</div>,
      wrap: true,
    },
    {
      name: <div className="headings">S/D OF</div>,
      selector: (row) => <div className="cellData">{row.sonOf.name}</div>,
      wrap: true,
    },
    {
      name: <div className="headings">STREAM</div>,
      selector: (row) => <div className="cellData">{row.stream}</div>,
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("semester")}>
          SEMESTER
        </div>
      ),
      selector: (row) => <div className="cellData">{row.semester}</div>,
      wrap: true,
      sortable: true,
    },
    {
      name: <div className="headings">HOSTEL</div>,
      selector: (row) => (
        <div className="cellData">{row.hostel === true ? "YES" : "NO"}</div>
      ),
      wrap: true,
    },
    {
      name: (
        <div className="headings" onClick={() => sortFunction("feeDue")}>
          FEE DUE
        </div>
      ),
      selector: (row) => <div className="cellData">{row.feeLeft}</div>,
      sortable: true,
      wrap: true,
    },
    {
      name: "",
      cell: (row) => (
        <a className="rlinks" href={`/update/collegeStudent/${row._id}`}>
          <button className="butn">EDIT</button>
        </a>
      ),
    },
    {
      name: "",
      cell: (row) => (
        <button
          onClick={() => {
            openDialog();
            makeId(row._id);
          }}
          className="delBtn"
        >
          DELETE
        </button>
      ),
    },
  ];

  const filterSubmit = (e) => {
    if (e) e.preventDefault();
    const filterParams = {
      batch,
      name,
      rollNo,
      hostel,
      degree,
      stream,
      semester,
      sortBy,
      sortOrder,
      limit: resultsPerPage,
      cursor,
    };
    dispatch(getAllCollegeStudents(filterParams));
  };

  useEffect(() => {
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (deleteError) {
      failure(deleteError);
      dispatch(clearErrors());
    }

    if (isDeleted === true) {
      successDelete();
      dispatch({ type: DELETE_CSTUDENT_RESET });
    }

    if (cursorChange) {
      filterSubmit();
      setCursorChange(false);
    } else if (sortChange) {
      filterSubmit();
      setSortChange(false);
    } else if (resetFilter) {
      filterSubmit();
      setResetFilter(false);
    } else if (resultsPerPageChange) {
      filterSubmit();
      setResultsPerPageChange(false);
    } else if (handleFilter) {
      filterSubmit();
      setHandleFilter(false);
    } else if (filterData) {
      dispatch(
        getAllCollegeStudents({
          ...filterData,
          limit: filterData.limit ? filterData.limit : 15,
        })
      );
      if (filterData.name) setName(filterData.name);
      if (filterData.batch) setBatch(filterData.batch);
      if (filterData.stream) setStream(filterData.stream);
      if (filterData.semester) setSemester(filterData.semester);
      if (filterData.degree) setDegree(filterData.degree);
      if (filterData.hostel) setHostel(filterData.hostel);
      if (filterData.rollNo) setRollNo(filterData.rollNo);
      if (filterData.sortBy) setSortBy(filterData.sortBy);
      if (filterData.sortOrder) setSortOrder(filterData.sortOrder);
      if (filterData.limit) setResultsPerPage(filterData.limit);
      if (filterData.cursor) setCursor(filterData.cursor);
    } else filterSubmit();
  }, [
    dispatch,
    error,
    deleteError,
    isDeleted,
    cursorChange,
    sortChange,
    resetFilter,
    resultsPerPageChange,
    handleFilter,
  ]);

  return (
    <Fragment>
      {loading || deleteLoading ? (
        <Loader />
      ) : (
        <Fragment>
          {isOpen && (
            <ReactDialogBox
              closeBox={closeDialog}
              modalWidth="28%"
              headerBackgroundColor="rgb(192, 188, 188)"
              headerTextColor="rgb(39, 39, 39)"
              headerHeight="50"
              closeButtonColor="#D92736"
              bodyBackgroundColor="white"
              bodyTextColor="black"
              bodyHeight="35%"
              headerText="Enter Admin Password"
            >
              <div>
                <form className="loginForm" onSubmit={deleteSubmit}>
                  <div className="password">
                    <label className="custom-label" htmlFor="password">
                      Password :
                    </label>
                    <div className="input-container">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Admin Password"
                        className="form-control filterSelect"
                        id="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                      />
                      <div
                        className="icon-container"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <FaEyeSlash /> : <FaEye />}
                      </div>
                    </div>
                  </div>
                  <button type="submit" className="btn btn-danger vmax1D">
                    DELETE
                  </button>
                </form>
              </div>
            </ReactDialogBox>
          )}
          <FeeSidebar />
          <div className="dashboard">
            <div className="filters">
              <div className="batchContainer filterDiv smallContainer">
                <label htmlFor="batchSelect">Batch</label>
                <select
                  id="batchSelect"
                  className="form-select filterSelect batch"
                  value={batch}
                  onChange={(e) => {
                    setBatch(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {batches.map((batch) => (
                    <option key={batch} value={batch}>
                      {batch}
                    </option>
                  ))}
                </select>
              </div>

              <div className="nameContainer filterDiv">
                <label htmlFor="nameInput">Name</label>
                <input
                  id="nameInput"
                  type="text"
                  className="form-control filterSelect name"
                  placeholder="Name"
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                  }}
                />
              </div>

              <div className="rollNoContainer filterDiv">
                <label htmlFor="rollNoInput">Roll Number</label>
                <input
                  id="rollNoInput"
                  type="text"
                  className="form-control rollNoSelect name"
                  placeholder="Roll Number"
                  value={rollNo}
                  onChange={(e) => {
                    setRollNo(e.target.value);
                  }}
                />
              </div>

              <div className="streamContainer filterDiv largeContainer">
                <label htmlFor="streamSelect">Stream</label>
                <select
                  id="streamSelect"
                  className="form-select streamSelect batch"
                  value={stream}
                  onChange={(e) => {
                    setStream(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {streams.map((stream) => (
                    <option key={stream} value={stream}>
                      {stream}
                    </option>
                  ))}
                </select>
              </div>

              <div className="degreeContainer filterDiv smallContainer">
                <label htmlFor="degreeSelect">Degree</label>
                <select
                  id="degreeSelect"
                  className="form-select degreeSelect batch"
                  value={degree}
                  onChange={(e) => {
                    setDegree(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {degrees.map((degree) => (
                    <option key={degree} value={degree}>
                      {degree}
                    </option>
                  ))}
                </select>
              </div>

              <div className="semesterContainer filterDiv smallContainer">
                <label htmlFor="semesterSelect">Semester</label>
                <select
                  id="semesterSelect"
                  className="form-select semesterSelect batch"
                  value={semester}
                  onChange={(e) => {
                    setSemester(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {[1, 2, 3, 4, 5, 6, 7, 8, "Passed"].map((semester) => (
                    <option key={semester} value={semester !== "Passed" ? semester : 100}>
                      {semester}
                    </option>
                  ))}
                </select>
              </div>

              <div className="hostelContainer filterDiv smallContainer">
                <label htmlFor="hostelSelect">Hostel</label>
                <select
                  id="hostelSelect"
                  className="form-select hostelSelect batch"
                  value={hostel}
                  onChange={(e) => {
                    setHostel(e.target.value);
                  }}
                >
                  <option value="">Select</option>
                  {["YES", "NO"].map((hostel) => (
                    <option key={hostel} value={hostel}>
                      {hostel}
                    </option>
                  ))}
                </select>
              </div>

              <div className="filterButtons">
                <button
                  className="applyButton"
                  onClick={() => {
                    setCursor(0);
                    setHandleFilter(true);
                  }}
                >
                  APPLY
                </button>
                <button
                  className="resetButton"
                  onClick={() => {
                    setBatch("");
                    setName("");
                    setDegree("");
                    setHostel("");
                    setStream("");
                    setRollNo("");
                    setSemester("");
                    setSortBy("");
                    setSortOrder();
                    setCursor(0);
                    setResetFilter(true);
                  }}
                >
                  RESET
                </button>
              </div>
            </div>
            <div className="productListContainer">
              <DataTable
                columns={columns}
                data={collegeStudents}
                className="productListTable"
                highlightOnHover={true}
                persistTableHead={true}
                fixedHeader={true}
                striped={true}
                dense={true}
                customStyles={customStyles}
              />
              <div className="pagination">
                <div className="resultsPerPageBox">
                  <span>Results Per Page</span>
                  <select
                    className="form-select"
                    value={resultsPerPage}
                    onChange={handleResultsPerPageChange}
                  >
                    {[5, 15, 25, 50, 100].map((results) => (
                      <option key={results} value={results}>
                        {results} Students
                      </option>
                    ))}
                  </select>
                  <span>
                    Showing {cursor + 1} -{" "}
                    {Math.min(totalCount, cursor + resultsPerPage)} of{" "}
                    {totalCount}
                  </span>
                </div>
                <Pagination
                  count={Math.ceil(totalCount / resultsPerPage)}
                  color="primary"
                  onChange={handlePageChange}
                  page={Math.ceil(cursor / resultsPerPage) + 1}
                  siblingCount={2}
                />
              </div>
            </div>
          </div>
        </Fragment>
      )}
    </Fragment>
  );
};

export default SearchCollegeStudent;
