import React, { useState, useEffect, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { FaEye, FaEyeSlash } from "react-icons/fa6";

import "../Admin/UpdateProfile.css";
import Loader from "../layout/Loader/Loader";
import InventorySidebar from "../layout/Loader/InventorySidebar";
import {
  clearErrors,
  updateItem,
  getItemDetails,
} from "../../actions/inventoryActions";
import { UPDATE_ITEM_RESET } from "../../constants/inventoryConstant";

const UpdateItem = () => {
  const dispatch = useDispatch();
  const { id } = useParams();
  // const navigate = useNavigate();

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowFormatted = tomorrow.toISOString().split("T")[0];

  const { loading, isUpdated, error } = useSelector(
    (state) => state.itemProfile
  );
  const {
    loading: itemLoading,
    error: itemError,
    item,
  } = useSelector((state) => state.itemDetails);

  const [showPassword, setShowPassword] = useState(false);

  const [name, setName] = useState();
  const [lab, setLab] = useState();
  const [cost, setCost] = useState();
  const [damaged, setDamaged] = useState();
  const [dateOfPurchase, setDateOfPurchase] = useState();
  const [password, setPassword] = useState();

  const labs = [
    "BOTANY",
    "ZOOLOGY",
    "PHYSICS",
    "CHEMISTRY",
    "IT",
    "MESS",
    "INFRASTRUCTURE",
  ];

  const updateSubmit = (e) => {
    e.preventDefault();
    try {
      const data = {
        name,
        lab,
        cost,
        password,
        dateOfPurchase,
        damaged,
      };
      dispatch(updateItem(id, data));
    } catch (err) {}
  };

  const success = () => {
    toast.success("Item Updated Successfully");
  };
  const failure = (error) => {
    toast.error(error);
  };
  useEffect(() => {
    if (!item || (item && item._id !== id)) dispatch(getItemDetails(id));
    else {
      setName(item.name);
      setCost(item.cost);
      setLab(item.lab);
      setDamaged(item.damaged);
      setDateOfPurchase(item.dateOfPurchase);
    }
    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (error) {
      failure(error);
      dispatch(clearErrors());
    }

    if (isUpdated) {
      //  alert.success("Profile updated successfully");
      success();
      dispatch({ type: UPDATE_ITEM_RESET });
      dispatch(getItemDetails(id));
    }
  }, [dispatch, error, isUpdated, id, item]);

  return (
    <Fragment>
      {loading ? (
        <Loader />
      ) : (
        <div className="cardUPR">
          <InventorySidebar />
          <h4>Update Item</h4>
          <form className="loginForm" onSubmit={updateSubmit}>
            <div className="loginPhone">
              <label className="custom-label" htmlFor="name">
                Name :
              </label>
              <input
                type="text"
                placeholder="name"
                className="form-control filterSelect"
                id="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="cost">
                Cost :
              </label>
              <input
                type="number"
                placeholder="cost"
                className="form-control filterSelect"
                id="cost"
                required
                value={cost}
                onChange={(e) => setCost(e.target.value)}
              />
            </div>
            <div className="password">
              <label className="custom-label" id="damaged">
                Damaged :
              </label>
              <input
                type="number"
                placeholder="damaged"
                className="form-control filterSelect"
                id="damaged"
                required
                value={damaged}
                onChange={(e) => setDamaged(e.target.value)}
              />
            </div>
            <div>
              <label className="custom-label" htmlFor="lab">
                Lab :
              </label>
              <select
                onChange={(e) => setLab(e.target.value)}
                className="form-select form-input"
                id="lab"
              >
                <option value="">{lab ? lab : "Select Lab"}</option>
                {labs.map((cate) => (
                  <option key={cate} value={cate}>
                    {cate}
                  </option>
                ))}
              </select>
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="dateOfPurchase">
                Date of Purchase :
              </label>
              <input
                type="date"
                placeholder="date of purchase"
                className="form-control filterSelect"
                id="dateOfPurchase"
                value={dateOfPurchase}
                onChange={(e) => setDateOfPurchase(e.target.value)}
                max={tomorrowFormatted}
              />
            </div>
            <div className="password">
              <label className="custom-label" htmlFor="password">
                Password :
              </label>
              <div className="input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  className="form-control filterSelect"
                  id="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <div
                  className="icon-container"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </div>
              </div>
            </div>
            <input
              type="submit"
              value="UPDATE"
              className="btn btn-primary vmax1D"
            />
          </form>
        </div>
      )}
    </Fragment>
  );
};
export default UpdateItem;
