import {
  CREATE_CSTUDENT_FAIL,
  CREATE_CSTUDENT_REQUEST,
  CLEAR_ERRORS,
  CREATE_CSTUDENT_RESET,
  CREATE_CSTUDENT_SUCCESS,
  ALL_CSTUDENTS_FAIL,
  ALL_CSTUDENTS_REQUEST,
  ALL_CSTUDENTS_SUCCESS,
  CSTUDENT_DETAILS_FAIL,
  CSTUDENT_DETAILS_REQUEST,
  CSTUDENT_DETAILS_SUCCESS,
  DELETE_CSTUDENT_FAIL,
  DELETE_CSTUDENT_REQUEST,
  DELETE_CSTUDENT_RESET,
  DELETE_CSTUDENT_SUCCESS,
  UPDATE_CSTUDENT_FAIL,
  UPDATE_CSTUDENT_REQUEST,
  UPDATE_CSTUDENT_RESET,
  UPDATE_CSTUDENT_SUCCESS,
  PAYMENT_CSTUDENT_FAIL,
  PAYMENT_CSTUDENT_REQUEST,
  PAYMENT_CSTUDENT_RESET,
  PAYMENT_CSTUDENT_SUCCESS,
  UPDATE_SEM_FAIL,
  UPDATE_SEM_REQUEST,
  UPDATE_SEM_RESET,
  UPDATE_SEM_SUCCESS,
  CREATE_CSTUDENT_EXCEL_REQUEST,
  CREATE_CSTUDENT_EXCEL_SUCCESS,
  CREATE_CSTUDENT_EXCEL_FAIL,
  STUDENT_PASSED_FAIL,
  STUDENT_PASSED_REQUEST,
  STUDENT_PASSED_RESET,
  STUDENT_PASSED_SUCCESS
} from "../constants/collegeStudentConstant";

import axios from "axios";

//create student
export const createCollegeStudent =
  (collegeStudentData) => async (dispatch) => {
    try {
      dispatch({ type: CREATE_CSTUDENT_REQUEST });

      const config = { headers: { "Content-Type": "application/json" } };
      const { data } = await axios.post(
        `/api/v1/collegeStudent/create`,
        collegeStudentData,
        config
      );
      dispatch({ type: CREATE_CSTUDENT_SUCCESS, payload: data });
    } catch (error) {
      dispatch({
        type: CREATE_CSTUDENT_FAIL,
        payload: error.response.data.message,
      });
    }
  };

  // create from excel
  export const createCollegeStudentFromExcelFile =
  (formData) => async (dispatch) => {
    try {
      dispatch({ type: CREATE_CSTUDENT_EXCEL_REQUEST });

      const config = { headers: { "Content-Type": "multipart/form-data" } };
      const { data } = await axios.post(
        `/api/v1/collegeStudent/create/file`,
        formData,
        config
      );
      dispatch({ type: CREATE_CSTUDENT_EXCEL_SUCCESS, payload: data });
    } catch (error) {
      dispatch({
        type: CREATE_CSTUDENT_EXCEL_FAIL,
        payload: error.response.data.message,
      });
    }
  };

// get All Students
export const getAllCollegeStudents = (filterData) => async (dispatch) => {
  try {
    dispatch({ type: ALL_CSTUDENTS_REQUEST , payload:filterData });
    if (filterData && filterData.batch) {
      if (!filterData.rollNo)
        filterData.rollNo =
          filterData.batch.length >= 2
            ? filterData.batch.slice(-2) + "-"
            : filterData.batch;
      delete filterData.batch;
    }
    let url = "/api/v1/collegeStudents";
    if (filterData) {
      const filteredData = Object.fromEntries(
        Object.entries(filterData).filter(([_, value]) => (value !== undefined && value !== ""))
      );

      const queryParams = new URLSearchParams(filteredData).toString();
      if (queryParams) {
        url += `?${queryParams}`;
      }
    }
    const { data } = await axios.get(url);

    dispatch({ type: ALL_CSTUDENTS_SUCCESS, payload:data });
  } catch (error) {
    dispatch({ type: ALL_CSTUDENTS_FAIL, payload: error });
  }
};

// get  Student Details
export const getCollegeStudentDetails = (id) => async (dispatch) => {
  try {
    dispatch({ type: CSTUDENT_DETAILS_REQUEST });
    const { data } = await axios.get(`/api/v1/collegeStudent/${id}`);

    dispatch({ type: CSTUDENT_DETAILS_SUCCESS, payload: data.collegeStudent });
  } catch (error) {
    dispatch({
      type: CSTUDENT_DETAILS_FAIL,
      payload: error.response.data.message,
    });
  }
};

